23	using domi::ONNX;
24	using namespace ge::parser;
25	
26	namespace ge {
27	namespace {
28	const char *kData = "Data";
29	}
30	Status OnnxDataParser::ParseParams(const Message *op_src, ge::Operator &op_def) {
31	  GE_CHECK_NOTNULL(op_src);
32	  const ge::onnx::NodeProto *node_src = PtrToPtr<const Message, const ge::onnx::NodeProto>(op_src);
33	  GE_CHECK_NOTNULL(node_src);
34	  GELOGD("Onnx op node name = %s, op type= %s, parse params", node_src->name().c_str(), node_src->op_type().c_str());
35	  if (ParseInputFromModel(op_src, op_def) != SUCCESS) {
36	    GELOGE(FAILED, "[Parse][Shape] of data op %s from model failed", ParserUtils::GetOperatorName(op_def).c_str());
37	    return FAILED;
38	  }
39	  // Subgraph data operator don't need parse input shape
40	  // the shape mappings from parent node input
41	  if (IsSubgraphDataOp()) {
42	    return SUCCESS;
43	  }
44	
45	  if (ParseInputFromUser(op_def) != SUCCESS) {
46	    GELOGE(FAILED, "[Parse][Shape] of data op %s from user failed", ParserUtils::GetOperatorName(op_def).c_str());
47	    return FAILED;
48	  }
49	
50	  ge::TensorDesc tensor_desc;
51	  tensor_desc.SetShape(ge::Shape(user_input_dims_v_));
52	  tensor_desc.SetOriginShape(ge::Shape(user_input_dims_v_));
53	  int64_t type = 1;
54	  (void)op_def.GetAttr(ge::DATA_ATTR_NAME_DATA_TYPE.c_str(), type);
55	  tensor_desc.SetDataType(static_cast<DataType>(type));
56	
57	  auto op_desc = ge::OpDescUtils::GetOpDescFromOperator(op_def);
58	  op_def.UpdateInputDesc(op_desc->GetInputNameByIndex(0).c_str(), tensor_desc);
59	  op_def.UpdateOutputDesc(op_desc->GetOutputNameByIndex(0).c_str(), tensor_desc);
60	
61	  return SUCCESS;
62	}
63	
64	int64_t OnnxDataParser::ParseInputTensor(const ge::onnx::AttributeProto &attribute) {
65	  const ::ge::onnx::TensorProto it_tensor = attribute.t();
66	  int64_t data_type = it_tensor.data_type();
67	  GELOGI("Attr name: %s, data type: %ld ", attribute.name().c_str(), data_type);
68	  for (auto dim : it_tensor.dims()) {
69	    model_input_dims_v_.push_back(dim);
70	  }
71	  return data_type;
72	}
73	
74	Status OnnxDataParser::ParseInputFromModel(const Message *op_src, ge::Operator &op_def) {
75	  GE_CHECK_NOTNULL(op_src);
76	  const ge::onnx::NodeProto *node = PtrToPtr<const Message, const ge::onnx::NodeProto>(op_src);
77	  GE_CHECK_NOTNULL(node);
78	
79	  // Get attr t:'input_tensor' form NodeProto
80	  int64_t data_type = 1;
81	  int64_t index = 0;
82	  is_subgraph_data_op_ = false;
83	  for (auto it : node->attribute()) {
84	    if (it.name() == ge::kAttrNameInput) {
85	      data_type = ParseInputTensor(it);
86	    } else if (it.name() == ge::kAttrNameIndex) {
87	      index = it.i();
88	      GELOGI("The node has attribute with index: %ld", index);
89	    } else if (it.name() == ge::kAttrNameIsSubgraphOp) {
90	      is_subgraph_data_op_ = true;
91	    }
92	  }
93	
94	  op_def.SetAttr(ge::ATTR_NAME_INDEX.c_str(), index);
95	  if (IsSubgraphDataOp()) {
96	    return SUCCESS;
97	  }
98	
99	  // Trans onnx type to ge type
100	  DataType type = OnnxUtil::ConvertOnnxDataType(data_type);
101	  if (type == ge::DataType::DT_UNDEFINED) {
102	    REPORT_INNER_ERR_MSG("E19999", "tensor_proto data type %" PRId64 " is undefined.", data_type);
103	    GELOGE(domi::PARAM_INVALID, "[Check][Param]tensor_proto data type %" PRId64 " is undefined.", data_type);
104	    return FAILED;
105	  }
106	  op_def.SetAttr(ge::DATA_ATTR_NAME_DATA_TYPE.c_str(), static_cast<int64_t>(type));
107	
108	  return SUCCESS;
109	}
110	
111	Status OnnxDataParser::ParseInputFromUser(const ge::Operator &op_def) {
112	  std::map<std::string, std::vector<int64_t>> input_dims = GetParserContext().input_dims;
113	  // User not designate the input_shape
114	  std::string name = ParserUtils::GetOperatorName(op_def);
115	  if (input_dims.count(name) == 0) {
116	    GELOGI("input shape of node %s is not designated ,need parse from model", name.c_str());
117	    for (uint32_t i = 0; i < model_input_dims_v_.size(); i++) {
118	      user_input_dims_v_.push_back(model_input_dims_v_[i]);
119	    }
120	    return SUCCESS;
121	  }
122	
123	  /// User designate the input_shape by passing '--input_shape=xxx:x,x,x,x'
124	  /// Two cases below both OK:
125	  /// 1. the input_shape not defined in the model(dimension is 0).
126	  /// 2. the input_shape defined in the model(dimension greater than 0), and the dimension matches with user
127	  /// designate_dim.
128	  std::vector<int64_t> designated_dims = input_dims.at(name);
129	  size_t input_dim_size = designated_dims.size();
130	  if (!(model_input_dims_v_.empty() || input_dim_size == model_input_dims_v_.size())) {
131	    GELOGD("user designated input_dim_num %zu does match input_dim_num %zu defined by model", input_dim_size,
132	           model_input_dims_v_.size());
133	    return domi::PARAM_INVALID;
134	  }
135	
136	  // replace with the user designated_dims
137	  user_input_dims_v_.swap(designated_dims);
138	
139	  return SUCCESS;
140	}
141	
142	REGISTER_OP_PARSER_CREATOR(ONNX, kData, OnnxDataParser);
143	}  // namespace ge
