10	
11	#include "onnx_constant_parser.h"
12	#include <cinttypes>
13	#include <map>
14	#include <vector>
15	#include "parser/common/acl_graph_parser_util.h"
16	
17	#include "framework/omg/parser/parser_inner_ctx.h"
18	#include "graph/ge_tensor.h"
19	#include "graph/utils/tensor_adapter.h"
20	#include "parser/common/op_parser_factory.h"
21	#include "parser/onnx/onnx_util.h"
22	#include "base/err_msg.h"
23	
24	using domi::ONNX;
25	using ge::onnx::NodeProto;
26	using ge::onnx::TensorProto;
27	using GeShape = ge::GeShape;
28	using GeTensorDesc = ge::GeTensorDesc;
29	using namespace ge::parser;
30	
31	namespace ge {
32	namespace {
33	const char *kConstant = "Const";
34	}
35	Status OnnxConstantParser::ParseConvertData(const ge::onnx::TensorProto &tensor_proto, ge::Tensor &tensor, int count) {
36	  int64_t data_type = tensor_proto.data_type();
37	  if (ge::OnnxUtil::ConvertOnnxDataType(data_type) == ge::DataType::DT_UNDEFINED) {
38	    REPORT_INNER_ERR_MSG("E19999", "data_type %" PRId64 " not support.", data_type);
39	    GELOGE(FAILED, "[Check][Param] data_type %" PRId64 " not support.", data_type);
40	    return FAILED;
41	  }
42	
43	  if (count == 0) {
44	    GELOGI("At least one dim equals zero, result in the count equal to zero.");
45	    return SUCCESS;
46	  }
47	
48	  std::map<uint32_t, int32_t> datatype_val_size_map = {
49	      // for int32, uint8, int8, uint16, int16, bool, and float16 values
50	      {OnnxDataType::INT32, tensor_proto.int32_data_size()},
51	      {OnnxDataType::UINT8, tensor_proto.int32_data_size()},
52	      {OnnxDataType::INT8, tensor_proto.int32_data_size()},
53	      {OnnxDataType::UINT16, tensor_proto.int32_data_size()},
54	      {OnnxDataType::INT16, tensor_proto.int32_data_size()},
55	      {OnnxDataType::BOOL, tensor_proto.int32_data_size()},
56	      {OnnxDataType::FLOAT16, tensor_proto.int32_data_size()},
57	      {OnnxDataType::BFLOAT16, tensor_proto.int32_data_size()},
58	      // for int64 values
59	      {OnnxDataType::INT64, tensor_proto.int64_data_size()},
60	      // for string values
61	      {OnnxDataType::STRING, tensor_proto.string_data_size()},
62	      // for float and complex64 values
63	      {OnnxDataType::FLOAT, tensor_proto.float_data_size()},
64	      {OnnxDataType::COMPLEX64, tensor_proto.float_data_size()},
65	      // for double and complex128 values
66	      {OnnxDataType::DOUBLE, tensor_proto.double_data_size()},
67	      {OnnxDataType::COMPLEX128, tensor_proto.double_data_size()},
68	      // for uint64 and uint32 values
69	      {OnnxDataType::UINT64, tensor_proto.uint64_data_size()},
70	      {OnnxDataType::UINT32, tensor_proto.uint64_data_size()},
71	  };
72	
73	  int32_t datatype_val_size = 0;
74	  std::map<uint32_t, int32_t>::const_iterator iter = datatype_val_size_map.find(data_type);
75	  if (iter != datatype_val_size_map.end()) {
76	    datatype_val_size = iter->second;
77	  } else {
78	    REPORT_INNER_ERR_MSG("E19999", "data_type %" PRId64 " not support.", data_type);
79	    GELOGE(domi::PARAM_INVALID, "[Find][DataType]data_type %" PRId64 " not support.", data_type);
80	    return FAILED;
81	  }
82	
83	  // find raw data
84	  if (datatype_val_size == 0) {
85	    if (tensor_proto.raw_data().empty()) {
86	      REPORT_INNER_ERR_MSG("E19999", "tensor_proto has no elements or raw_data");
87	      GELOGE(domi::PARAM_INVALID, "[Check][Param]tensor_proto has no elements or raw_data");
88	      return FAILED;
89	    }
90	
91	    if (data_type == OnnxDataType::STRING) {
92	      tensor.SetData(tensor_proto.raw_data().c_str());
93	    } else {
94	      tensor.SetData(PtrToPtr<const char_t, const uint8_t>(tensor_proto.raw_data().c_str()),
95	                     tensor_proto.raw_data().size());
96	    }
97	    GELOGD("Raw data size is : %zu", tensor_proto.raw_data().size());
98	    return SUCCESS;
99	  }
100	
101	  // find _data() elements
102	  ParseConvertDataElements(tensor_proto, tensor, count, data_type);
103	  return SUCCESS;
104	}
105	
106	void OnnxConstantParser::ParseConvertDataElements(const ge::onnx::TensorProto &tensor_proto, ge::Tensor &tensor,
107	                                                  int count, int64_t data_type) {
108	  switch (data_type) {
109	    // for int32, uint8, int8, uint16, int16, bool, and float16 values
110	    case OnnxDataType::INT32:
111	    case OnnxDataType::UINT8:
112	    case OnnxDataType::INT8:
113	    case OnnxDataType::UINT16:
114	    case OnnxDataType::INT16:
115	    case OnnxDataType::BOOL:
116	    case OnnxDataType::FLOAT16:
117	    case OnnxDataType::BFLOAT16:
118	      (void)SetTensorData(tensor_proto.int32_data_size(), tensor_proto.int32_data(), count, tensor);
119	      break;
120	    // for int64 values
121	    case OnnxDataType::INT64:
122	      (void)SetTensorData(tensor_proto.int64_data_size(), tensor_proto.int64_data(), count, tensor);
123	      break;
124	    // for string values
125	    case OnnxDataType::STRING: {
126	      std::vector<AscendString> data;
127	      for (auto str_data : tensor_proto.string_data()) {
128	        data.emplace_back(AscendString(str_data.c_str()));
129	      }
130	      tensor.SetData(data);
131	      break;
132	    }
133	    // for float and complex64 values
134	    case OnnxDataType::FLOAT:
135	      (void)SetTensorData(tensor_proto.float_data_size(), tensor_proto.float_data(), count, tensor);
136	      break;
137	    case OnnxDataType::COMPLEX64:
138	      (void)SetTensorData(tensor_proto.float_data_size(), tensor_proto.float_data(), tensor_proto.float_data_size(),
139	                          tensor);
140	      break;
141	    // for double and complex128 values
142	    case OnnxDataType::DOUBLE:
143	      (void)SetTensorData(tensor_proto.double_data_size(), tensor_proto.double_data(), count, tensor);
144	      break;
145	    case OnnxDataType::COMPLEX128:
146	      (void)SetTensorData(tensor_proto.double_data_size(), tensor_proto.double_data(), tensor_proto.double_data_size(),
147	                          tensor);
148	      break;
149	    // for uint64 and uint32 values
150	    case OnnxDataType::UINT64:
151	    case OnnxDataType::UINT32:
152	      (void)SetTensorData(tensor_proto.uint64_data_size(), tensor_proto.uint64_data(), count, tensor);
153	      break;
154	    default:
155	      break;
156	  }
157	}
158	
159	Status OnnxConstantParser::ParseConvertTensor(const ge::onnx::TensorProto &tensor_proto, ge::Tensor &tensor) {
160	  // convert shape and format
161	  std::vector<int64_t> tmp_shape;
162	  int count = 1;
163	  for (int i = 0; i < tensor_proto.dims_size(); i++) {
164	    tmp_shape.push_back(tensor_proto.dims(i));
165	    int64_t dim = tmp_shape[i];
166	    // support weights shape [0],have no weights
167	    if (dim < 0 || (count != 0 && (dim >= INT64_MAX / count))) {
168	      REPORT_INNER_ERR_MSG("E19999", "Dim size is invalid, dim is less than zero or dim size exceeds INT64_MAX.");
169	      GELOGE(FAILED, "[Check][Param] Dim size is invalid, dim is less than zero or dim size exceeds INT64_MAX.");
170	      return FAILED;
171	    }
172	    count *= dim;
173	  };
174	  TensorDesc tensor_desc = tensor.GetTensorDesc();
175	  tensor_desc.SetShape(ge::Shape(tmp_shape));
176	  tensor.SetTensorDesc(tensor_desc);
177	
178	  // set data
179	  if (ParseConvertData(tensor_proto, tensor, count) != SUCCESS) {
180	    GELOGE(FAILED, "[Invoke][ParseConvertData]Convert ge tensor data and format failed.");
181	    return FAILED;
182	  }
183	  return SUCCESS;
184	}
185	
186	Status OnnxConstantParser::ParseConvertDataType(const ge::onnx::TensorProto &tensor_proto, ge::Tensor &tensor) {
187	  int64_t data_type = tensor_proto.data_type();
188	  ge::DataType type = ge::OnnxUtil::ConvertOnnxDataType(data_type);
189	  if (type == ge::DataType::DT_UNDEFINED) {
190	    REPORT_INNER_ERR_MSG("E19999", "tensor_proto data type %" PRId64 " is undefined.", data_type);
191	    GELOGE(domi::PARAM_INVALID, "[Check][Param] tensor_proto data type %" PRId64 " is undefined.", data_type);
192	    return FAILED;
193	  }
194	
195	  TensorDesc tensor_desc = tensor.GetTensorDesc();
196	  tensor_desc.SetDataType(ge::DataType(type));
197	  tensor.SetTensorDesc(tensor_desc);
198	  return SUCCESS;
199	}
200	
201	Status OnnxConstantParser::ParseConstFromInput(const ge::onnx::NodeProto *op_src, ge::Operator &op_def) {
202	  GE_CHECK_NOTNULL(op_src);
203	  const NodeProto *node = PtrToPtr<const ge::onnx::NodeProto, const NodeProto>(op_src);
204	
205	  // Get const Tensor from node
206	  Tensor tensor;
207	  for (auto it : node->attribute()) {
208	    if (it.name() != ge::kAttrNameValue) {
209	      continue;
210	    }
211	    const ::ge::onnx::TensorProto it_tensor = it.t();
212	    if (ParseConvertDataType(it_tensor, tensor) != SUCCESS) {
213	      GELOGE(FAILED, "[Check][Param] Convert ge tensor data type failed, attribute name is %s.", it.name().c_str());
214	      return FAILED;
215	    }
216	
217	    if (ParseConvertTensor(it_tensor, tensor) != SUCCESS) {
218	      GELOGE(FAILED, "[Check][Param] Convert ge tensor shape and format failed, attribute name is %s.",
219	             it.name().c_str());
220	      return FAILED;
221	    }
222	  }
223	
224	  op_def.SetAttr(ge::kAttrNameValue, tensor);
225	  return SUCCESS;
226	}
227	
228	Status OnnxConstantParser::ParseParams(const Message *op_src, ge::Operator &op_def) {
229	  GE_CHECK_NOTNULL(op_src);
230	  const ge::onnx::NodeProto *node = PtrToPtr<const Message, const ge::onnx::NodeProto>(op_src);
231	  GE_CHECK_NOTNULL(node);
232	  GELOGD("Onnx op node name = %s, op type= %s, parse params", node->name().c_str(), node->op_type().c_str());
233	
234	  if (ParseConstFromInput(node, op_def) != SUCCESS) {
235	    GELOGE(FAILED, "[Parse][Constant] node %s failed", node->name().c_str());
236	    return FAILED;
237	  }
238	  return SUCCESS;
239	}
