187	Status GenSubgraphParseTasks(const ge::ComputeGraphPtr &parent_graph, std::deque<ParseArg> &args) {
188	  GELOGI("Generate subgraph parse tasks start");
189	  for (auto &node : parent_graph->GetDirectNode()) {
190	    auto op_desc = node->GetOpDesc();
191	    GE_CHECK_NOTNULL(op_desc);
192	    for (const auto &subgraph_name_to_index : op_desc->GetSubgraphNameIndexes()) {
193	      auto i = subgraph_name_to_index.second;
194	      auto subgraph_iname = subgraph_name_to_index.first;
195	      if (subgraph_iname.empty()) {
196	        GELOGW("The subgraph index %u of node %s is empty", i, node->GetName().c_str());
197	        continue;
198	      }
199	
200	      // change the graph name to ensure it is unique in GE
201	      std::string unique_subgraph_name;
202	      OnnxUtil::GenUniqueSubgraphName(i, subgraph_iname, node->GetName(), unique_subgraph_name);
203	
204	      GELOGD("Add subgraph parse task to the queue, node %s, index %u, subgraph instance name %s",
205	             node->GetName().c_str(), i, unique_subgraph_name.c_str());
206	      args.push_back({nullptr, node, unique_subgraph_name, i});
207	    }
208	  }
209	  GELOGI("Generate subgraph parse tasks end");
210	  return SUCCESS;
