230	Status PostOpProcessForSubgraph(const ParseArg &arg, ge::ComputeGraphPtr sub_graph) {
231	  if (arg.parent_node == nullptr) {
232	    return SUCCESS;
233	  }
234	  std::string op_type = arg.parent_node->GetType();
235	  std::string op_name = arg.parent_node->GetName();
236	  domi::ParseSubgraphFuncV2 parse_func_v2 = nullptr;
237	  auto post_func = domi::OpRegistry::Instance()->GetParseSubgraphPostFunc(op_type, domi::ONNX);
238	  if (post_func == nullptr) {
239	    GELOGW("The subgraph post func for node %s type %s is null", op_name.c_str(), op_type.c_str());
240	    if (domi::OpRegistry::Instance()->GetParseSubgraphPostFunc(op_type, domi::ONNX, parse_func_v2) != SUCCESS ||
241	        parse_func_v2 == nullptr) {
242	      GELOGW("The subgraph post func v2 for node %s type %s is null", op_name.c_str(), op_type.c_str());
243	      return SUCCESS;
244	    }
245	  }
246	
247	  GELOGD("Post process for node %s with type %s in subgraph %s ", arg.graph_name.c_str(),
248	         arg.parent_node->GetType().c_str(), arg.parent_node->GetName().c_str());
249	
250	  // Refresh node_name in subgraph
251	  for (const ge::NodePtr &node : sub_graph->GetDirectNode()) {
252	    if (node->GetOpDesc() == nullptr) {
253	      continue;
254	    }
255	    node->GetOpDesc()->SetName(OnnxUtil::GenUniqueNodeName(sub_graph->GetName(), node->GetName()));
256	  }
257	
258	  auto graph = ge::GraphUtilsEx::CreateGraphFromComputeGraph(sub_graph);
259	  Status ret = FAILED;
260	  if (post_func != nullptr) {
261	    ret = post_func(arg.graph_name, graph);
262	  } else if (parse_func_v2 != nullptr) {
263	    ret = parse_func_v2(arg.graph_name.c_str(), graph);
264	  }
265	  if (ret != SUCCESS) {
266	    GELOGE(FAILED, "[PostProcess][Subgraph]Failed to post-process subgraph %s on node %s type %s",
267	           arg.graph_name.c_str(), arg.parent_node->GetName().c_str(), arg.parent_node->GetType().c_str());
268	    REPORT_INNER_ERR_MSG("E19999", "Failed to post-process subgraph %s on node %s type %s", arg.graph_name.c_str(),
269	                         arg.parent_node->GetName().c_str(), arg.parent_node->GetType().c_str());
270	    return FAILED;
271	  }
272	  return SUCCESS;
273	}
