276	Status OnnxModelParser::ParseOutput(ge::onnx::GraphProto &onnx_graph) {
277	  if (onnx_graph.output_size() == 0) {
278	    GELOGE(FAILED, "[Parse][Output] Onnx graph:%s has zero output", onnx_graph.name().c_str());
279	    REPORT_PREDEFINED_ERR_MSG("E16001", std::vector<const char_t *>({"value"}),
280	                              std::vector<const char_t *>({"output"}));
281	    return FAILED;
282	  }
283	
284	  // get output value info map
285	  for (int i = 0; i < onnx_graph.output_size(); i++) {
286	    ge::onnx::ValueInfoProto value_info = onnx_graph.output(i);
287	    GELOGI("The index of %d output name : %s.", i, value_info.name().c_str());
288	    output_node_names_.emplace_back(value_info.name());
289	  }
290	  return SUCCESS;
291	}
