293	Status OnnxModelParser::ParseInput(const std::map<std::string, ge::onnx::TensorProto> &initializer_name_tensor,
294	                                   bool is_subgraph, ge::onnx::GraphProto &onnx_graph) {
295	  if (!is_subgraph && onnx_graph.input_size() == 0) {
296	    GELOGE(FAILED, "[Parse][Input] Root onnx graph:%s has zero input", onnx_graph.name().c_str());
297	    REPORT_PREDEFINED_ERR_MSG("E16001", std::vector<const char_t *>({"value"}), std::vector<const char_t *>({"input"}));
298	    return FAILED;
299	  }
300	
301	  // get input value info map
302	  int64_t data_index = 0;
303	  for (int i = 0; i < onnx_graph.input_size(); i++) {
304	    ge::onnx::ValueInfoProto value_info = onnx_graph.input(i);
305	    GELOGI("The index of %d input name : %s.", i, value_info.name().c_str());
306	
307	    /// if the input is initialized by a default value found in ‘initializer’,
308	    /// it will be considered as a const node.
309	    auto initializer_iter = initializer_name_tensor.find(value_info.name());
310	    if (initializer_iter != initializer_name_tensor.end()) {
311	      continue;
312	    }
313	
314	    ge::onnx::TensorProto tensor_tmp;
315	    if (value_info.has_type()) {
316	      const ge::onnx::TypeProto type = value_info.type();
317	      if (type.has_tensor_type()) {
318	        const ge::onnx::TypeProto_Tensor type_proto_tensor = type.tensor_type();
319	        int32_t elem_type = type_proto_tensor.elem_type();
320	        tensor_tmp.set_data_type(elem_type);
321	        if (type_proto_tensor.has_shape()) {
322	          const ge::onnx::TensorShapeProto tensor_shape = type_proto_tensor.shape();
323	          for (int j = 0; j < tensor_shape.dim_size(); j++) {
324	            const ge::onnx::TensorShapeProto_Dimension dimension = tensor_shape.dim(j);
325	            int64_t dim_value = -1;
326	            if (dimension.value_case() == kDimValue) {
327	              dim_value = dimension.dim_value();
328	            }
329	            tensor_tmp.add_dims(dim_value);
330	            GELOGI("elem_type: %d, dim_value: %ld", elem_type, dim_value);
331	          }
332	        }
333	      }
334	    }
335	    // Construct node for input
336	    ge::onnx::NodeProto *input_node = onnx_graph.add_node();
337	    input_node->set_name(value_info.name());
338	    input_node->set_op_type(ge::kOpTypeInput);
339	    input_node->add_output(value_info.name());
340	    // add tensor
341	    ge::onnx::AttributeProto *attribute = input_node->add_attribute();
342	    attribute->set_name(ge::kAttrNameInput);
343	    ge::onnx::TensorProto *attribute_tensor = attribute->mutable_t();
344	    *attribute_tensor = tensor_tmp;
345	    // add index
346	    ge::onnx::AttributeProto *attribute_index = input_node->add_attribute();
347	    attribute_index->set_name(ge::kAttrNameIndex);
348	    attribute_index->set_i(data_index++);
349	    // add subgraph attr
350	    if (is_subgraph) {
351	      attribute = input_node->add_attribute();
352	      attribute->set_name(ge::kAttrNameIsSubgraphOp);
353	    }
354	    input_node_names_.emplace_back(value_info.name());
355	  }
356	  return SUCCESS;
357	}
