359	Status OnnxModelParser::ParseInitializer(ge::onnx::GraphProto &onnx_graph,
360	                                         std::map<std::string, ge::onnx::TensorProto> &initializer_name_tensor) const {
361	  // Construct const node for weight
362	  int index = 0;
363	  for (auto it : initializer_name_tensor) {
364	    ge::onnx::NodeProto *const_node = onnx_graph.add_node();
365	    std::string output_name = it.first + "_" + kInitializerKey + "_" + to_string(index++);
366	    const_node->set_name(output_name);
367	    const_node->add_output(it.first);
368	    ge::onnx::AttributeProto *attribute = const_node->add_attribute();
369	    attribute->set_name(ge::kAttrNameValue);
370	    ge::onnx::TensorProto *attribute_t = attribute->mutable_t();
371	    *attribute_t = it.second;
372	    if (it.second.data_location() == ge::onnx::TensorProto_DataLocation_EXTERNAL) {
373	      const_node->set_op_type(kFileConstant);
374	      GELOGD("Initializer const node [%s], the weight was stored in the file.", const_node->name().c_str());
375	    } else {
376	      const_node->set_op_type(ge::kOpTypeConstant);
377	      GELOGD("Initializer const node [%s].", const_node->name().c_str());
378	    }
379	  }
380	
381	  return SUCCESS;
382	}
