384	void OnnxModelParser::UpdateConstantOpType(ge::onnx::NodeProto *node) const {
385	  // If weight in file, Marker Constant(not Initializer) as file constant
386	  for (auto it : node->attribute()) {
387	    if (it.name() == ge::kAttrNameValue) {
388	      const ::ge::onnx::TensorProto tensor_proto = it.t();
389	      if (tensor_proto.data_location() == ge::onnx::TensorProto_DataLocation_EXTERNAL) {
390	        node->set_op_type(kFileConstant);
391	        GELOGD("Const node [%s], the weight was stored in the file.", node->name().c_str());
392	      }
393	      break;
394	    }
395	  }
396	}
