398	void OnnxModelParser::UpdateNodeNameAndOpType(ge::onnx::GraphProto &onnx_graph) const {
399	  int index = 0;
400	  for (int i = 0; i < onnx_graph.node_size(); i++) {
401	    ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
402	    if (node->name().empty()) {
403	      std::string node_name = node->op_type() + "_" + to_string(index++);
404	      node->set_name(node_name);
405	    }
406	    if (node->op_type() == kOpTypeConstant) {
407	      UpdateConstantOpType(node);
408	    }
409	  }
