412	Status OnnxModelParser::ConstructOriType(const ge::onnx::NodeProto *node_proto, std::string &ori_type) {
413	  GE_CHECK_NOTNULL(node_proto);
414	
415	  ori_type = node_proto->op_type();
416	  if (kOnnxOpMap.find(ori_type) != kOnnxOpMap.end()) {
417	    return SUCCESS;
418	  }
419	
420	  std::string domain = node_proto->domain().empty() ? "ai.onnx" : node_proto->domain();
421	  std::map<std::string, int64_t>::const_iterator it = domain_verseion_.find(domain);
422	  if (it == domain_verseion_.end()) {
423	    REPORT_INNER_ERR_MSG("E19999", "The opset of domain[%s] has no responding version.", domain.c_str());
424	    GELOGE(PARAM_INVALID, "[Check][Param]The opset of domain[%s] has no responding version.", domain.c_str());
425	    return PARAM_INVALID;
426	  }
427	  int64_t version = it->second;
428	
429	  ori_type = domain + "::" + to_string(version) + "::" + ori_type;
430	  return SUCCESS;
431	}
