433	Status OnnxModelParser::AdapterOpType(const ge::onnx::NodeProto *node_proto, std::string &ori_type,
434	                                      std::string &op_type) {
435	  GE_CHECK_NOTNULL(node_proto);
436	  ori_type = node_proto->op_type();
437	
438	  auto map_it = kOnnxOpMap.find(ori_type);
439	  if (map_it != kOnnxOpMap.end()) {
440	    op_type = map_it->second;
441	    ori_to_om_type_[ori_type] = op_type;
442	    return SUCCESS;
443	  }
444	
445	  Status ret = ConstructOriType(node_proto, ori_type);
446	  if (ret != SUCCESS) {
447	    GELOGE(ret, "[Construct][OriType] for [%s] failed.", ori_type.c_str());
448	    return ret;
449	  }
450	
451	  if (!domi::OpRegistry::Instance()->GetOmTypeByOriOpType(ori_type, op_type)) {
452	    REPORT_PREDEFINED_ERR_MSG("E16002", std::vector<const char *>({"optype"}),
453	                              std::vector<const char *>({ori_type.c_str()}));
454	    GELOGE(PARAM_INVALID, "[Get][OmType] according ori_type : %s failed.", ori_type.c_str());
455	    return PARAM_INVALID;
456	  }
457	
458	  ori_to_om_type_[ori_type] = op_type;
459	  return SUCCESS;
460	}
