462	Status OnnxModelParser::TransNodeToOperator(const ge::onnx::NodeProto *node_proto, ge::Operator &op,
463	                                            const string &op_type) const {
464	  GE_CHECK_NOTNULL(node_proto);
465	  string node_name = node_proto->name();
466	  op = ge::OperatorFactory::CreateOperator(node_name.c_str(), op_type.c_str());
467	  if (ParserUtils::GetOperatorName(op) != node_name) {
468	    REPORT_PREDEFINED_ERR_MSG("E10501", std::vector<const char_t *>({"opname", "optype"}),
469	                              std::vector<const char_t *>({node_name.c_str(), op_type.c_str()}));
470	    GELOGE(INTERNAL_ERROR, "[Creat][Op] IR for op[%s] optype[%s] is not registered.", node_name.c_str(),
471	           op_type.c_str());
472	    return INTERNAL_ERROR;
473	  }
474	
475	  GELOGI("After create operator, op[%s]: type[%s] have input size: %zu, output size: %zu",
476	         ParserUtils::GetOperatorName(op).c_str(), ParserUtils::GetOperatorType(op).c_str(), op.GetInputsSize(),
477	         op.GetOutputsSize());
478	  return SUCCESS;
