481	Status OnnxModelParser::ConstructInputOutputContext(const ge::onnx::NodeProto *node_proto) {
482	  GE_CHECK_NOTNULL(node_proto);
483	
484	  std::string node_name = node_proto->name();
485	  for (int i = 0; i < node_proto->input_size(); i++) {
486	    std::string input_name = node_proto->input(i);
487	    inputs_map_[input_name].emplace_back(node_name, i);
488	  }
489	
490	  for (int i = 0; i < node_proto->output_size(); i++) {
491	    std::string output_name = node_proto->output(i);
492	    outputs_map_[output_name].emplace_back(node_name, i);
493	  }
494	
495	  return SUCCESS;
