498	Status OnnxModelParser::SetOperatorInputs() {
499	  for (auto in_iter = inputs_map_.begin(); in_iter != inputs_map_.end(); in_iter++) {
500	    auto out_iter = outputs_map_.find(in_iter->first);
501	    if (out_iter == outputs_map_.end()) {
502	      GELOGW("Unknown input: %s:%d for node: %s, which maybe option input.", in_iter->first.c_str(),
503	             in_iter->second[0].second, in_iter->second[0].first.c_str());
504	      continue;
505	    }
506	
507	    std::vector<std::pair<std::string, int>> &input_node_indexs = in_iter->second;
508	    std::vector<std::pair<std::string, int>> &output_node_indexs = out_iter->second;
509	    for (auto input_node_index : input_node_indexs) {
510	      for (auto out_node_index : output_node_indexs) {
511	        std::map<std::string, ge::Operator>::const_iterator input_op_iter = name_operator_.find(input_node_index.first);
512	        if (input_op_iter == name_operator_.end()) {
513	          REPORT_INNER_ERR_MSG("E19999", "Node: %s cannot find in name_operator map.", input_node_index.first.c_str());
514	          GELOGE(INTERNAL_ERROR, "[Check][Param] Node: %s cannot find in name_operator map.",
515	                 input_node_index.first.c_str());
516	          return INTERNAL_ERROR;
517	        }
518	        std::map<std::string, ge::Operator>::const_iterator output_op_iter = name_operator_.find(out_node_index.first);
519	        if (output_op_iter == name_operator_.end()) {
520	          REPORT_INNER_ERR_MSG("E19999", "Node: %s cannot find in name_operator map.", out_node_index.first.c_str());
521	          GELOGE(INTERNAL_ERROR, "[Check][Param] Node: %s cannot find in name_operator map.",
522	                 out_node_index.first.c_str());
523	          return INTERNAL_ERROR;
524	        }
525	
526	        auto dst_op = input_op_iter->second;
527	        auto src_op = output_op_iter->second;
528	        int dst_index = input_node_index.second;
529	        int src_index = out_node_index.second;
530	        GELOGI("Start add output:%d of op:%s as input:%d of op:%s.", src_index,
531	               ParserUtils::GetOperatorName(src_op).c_str(), dst_index, ParserUtils::GetOperatorName(dst_op).c_str());
532	        auto dst_op_desc = ge::OpDescUtils::GetOpDescFromOperator(dst_op);
533	        GE_CHECK_NOTNULL(dst_op_desc);
534	        auto src_op_desc = ge::OpDescUtils::GetOpDescFromOperator(src_op);
535	        GE_CHECK_NOTNULL(src_op_desc);
536	        dst_op.SetInput(dst_op_desc->GetInputNameByIndex(dst_index).c_str(), src_op,
537	                        src_op_desc->GetOutputNameByIndex(src_index).c_str());
538	      }
539	    }
540	  }
541	  return SUCCESS;
542	}
