544	Status OnnxModelParser::Prechecker(ge::onnx::GraphProto &onnx_graph) {
545	  ge::PreChecker::Instance().Clear();
546	  for (int i = 0; i < onnx_graph.node_size(); i++) {
547	    ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
548	    std::string ori_type;
549	    Status ret = ConstructOriType(node, ori_type);
550	    if (ret != SUCCESS) {
551	      GELOGE(ret, "[Construct][OriType] for [%s] failed.", ori_type.c_str());
552	      return ret;
553	    }
554	    GELOGI("Construct ori type : %s ", ori_type.c_str());
555	    if (ge::PreChecker::Instance().AddOp(node, node->name(), ori_type) != SUCCESS) {
556	      REPORT_INNER_ERR_MSG("E19999", "AddOp failed, node:%s", node->name().c_str());
557	      GELOGE(FAILED, "[Add][NodeDef] to PreChecker failed, node name: %s.", node->name().c_str());
558	      return FAILED;
559	    }
560	    if (ge::PreChecker::Instance().CheckName(node) != SUCCESS) {
561	      REPORT_INNER_ERR_MSG("E19999", "CheckName failed for node:%s", node->name().c_str());
562	      GELOGE(FAILED, "[Check][Name] failed, node name: %s.", node->name().c_str());
563	      return FAILED;
564	    }
565	    if (kOnnxOpMap.find(ori_type) == kOnnxOpMap.end()) {
566	      if (ge::PreChecker::Instance().CheckType(node) != SUCCESS) {
567	        REPORT_INNER_ERR_MSG("E19999", "CheckType failed for node:%s", node->name().c_str());
568	        GELOGE(FAILED, "[Check][Type] failed, node name: %s.", node->name().c_str());
569	        return FAILED;
570	      }
571	    }
572	  }
573	  return SUCCESS;
574	}
