576	Status OnnxModelParser::ParseOpParam(const ge::onnx::NodeProto *node_proto, ge::Operator &op,
577	                                     std::shared_ptr<OpParser> &op_parser) const {
578	  GE_CHECK_NOTNULL(node_proto);
579	  GE_CHECK_NOTNULL(op_parser);
580	  std::string op_type = node_proto->op_type();
581	
582	  Status status = FAILED;
583	  domi::ParseParamByOpFunc parse_param_func = domi::OpRegistry::Instance()->GetParseParamByOperatorFunc(op_type);
584	  if (parse_param_func == nullptr) {
585	    status = op_parser->ParseParams(node_proto, op);
586	  } else {
587	    ge::Operator op_src(node_proto->name().c_str(), op_type.c_str());
588	    status = Message2Operator::ParseOperatorAttrs(node_proto, 1, op_src);
589	    if (status != SUCCESS) {
590	      REPORT_INNER_ERR_MSG("E19999", "Auto mapping node:%s(%s) to operator failed", node_proto->name().c_str(),
591	                           op_type.c_str());
592	      GELOGE(status, "Node[%s] auto mapping failed.", node_proto->name().c_str());
593	      return status;
594	    }
595	    std::shared_ptr<ge::OnnxCustomParserAdapter> onnx_custom_op_parser =
596	        std::dynamic_pointer_cast<ge::OnnxCustomParserAdapter>(op_parser);
597	    status = onnx_custom_op_parser->ParseParams(op_src, op);
598	    op_src.BreakConnect();
599	  }
600	
601	  if (status != SUCCESS) {
602	    REPORT_PREDEFINED_ERR_MSG("E11010", std::vector<const char *>({"opname", "optype"}),
603	                              std::vector<const char *>({node_proto->name().c_str(), op_type.c_str()}));
604	    GELOGE(status, "[Parse][Params] for op [%s] fail, optype [%s]", node_proto->name().c_str(), op_type.c_str());
605	    return status;
606	  }
607	
608	  return SUCCESS;
609	}
