611	Status OnnxModelParser::ParseAllNodeProto(ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
612	  for (int i = 0; i < onnx_graph.node_size(); i++) {
613	    ge::onnx::NodeProto *node_proto = onnx_graph.mutable_node(i);
614	    std::string node_name = node_proto->name();
615	    std::string ori_type = node_proto->op_type();
616	    GELOGI("Start parse node which name is %s, type is %s", node_name.c_str(), ori_type.c_str());
617	
618	    std::string op_type;
619	    Status status = AdapterOpType(node_proto, ori_type, op_type);
620	    if (status != SUCCESS) {
621	      GELOGE(status, "[Adapt][OpType] Adapter op type for ori type %s failed.", ori_type.c_str());
622	      return status;
623	    }
624	    node_proto->set_op_type(ori_type);
625	
626	    GELOGI("Trans original type:%s to op type:%s", ori_type.c_str(), op_type.c_str());
627	
628	    ge::Operator op;
629	    status = TransNodeToOperator(node_proto, op, op_type);
630	    if (status != SUCCESS) {
631	      GELOGE(status, "[Trans][Node] Trans node to operator for %s:%s failed.", node_name.c_str(), op_type.c_str());
632	      REPORT_INNER_ERR_MSG("E19999", "Trans node to operator for %s:%s failed.", node_name.c_str(), op_type.c_str());
633	      return status;
634	    }
635	
636	    // 7. op parser
637	    std::shared_ptr<ge::OpParserFactory> factory = ge::OpParserFactory::Instance(domi::ONNX);
638	    GE_CHECK_NOTNULL(factory);
639	    std::shared_ptr<ge::OpParser> op_parser = factory->CreateOpParser(op_type);
640	    GE_CHECK_NOTNULL(op_parser);
641	    status = ParseOpParam(node_proto, op, op_parser);
642	    if (status != SUCCESS) {
643	      GELOGE(status, "[Parse][Params] for %s:%s failed ret:%d.", node_name.c_str(), op_type.c_str(), status);
644	      return status;
645	    }
646	
647	    GELOGI("After ParseParams, op[%s]: type[%s] have input size: %zu, output size: %zu",
648	           ParserUtils::GetOperatorName(op).c_str(), ParserUtils::GetOperatorType(op).c_str(), op.GetInputsSize(),
649	           op.GetOutputsSize());
650	
651	    ge::graphStatus graph_status = graph.AddOp(op);
652	    if (graph_status != ge::GRAPH_SUCCESS) {
653	      GELOGE(FAILED, "[Add][Op] Add op:%s to graph failed.", ParserUtils::GetOperatorName(op).c_str());
654	      REPORT_INNER_ERR_MSG("E19999", "Add op:%s to graph failed.", ParserUtils::GetOperatorName(op).c_str());
655	      return FAILED;
656	    }
657	    name_operator_[ParserUtils::GetOperatorName(op)] = op;
658	
659	    // 8. Construct input output relation of every node
660	    status = ConstructInputOutputContext(node_proto);
661	    if (status != SUCCESS) {
662	      REPORT_INNER_ERR_MSG("E19999", "ConstructInputOutputContext failed.");
663	      GELOGE(status, "[Construct][RelationMap] to input and output failed.");
664	      return status;
665	    }
666	  }
667	  GELOGI("Parse all node proto success.");
668	  return SUCCESS;
669	}
