671	Status OnnxModelParser::GetGraphInputs(ge::onnx::GraphProto &onnx_graph, std::vector<ge::Operator> &input_ops) {
672	  if (input_node_names_.empty()) {
673	    // subgraph might not have input, we use constant nodes as the start nodes of the graph,
674	    for (int i = 0; i < onnx_graph.node_size(); i++) {
675	      ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
676	      if (node->op_type() == kOpTypeConstant) {
677	        input_node_names_.emplace_back(node->name());
678	      }
679	    }
680	  }
681	  for (auto in_name : input_node_names_) {
682	    std::map<std::string, ge::Operator>::const_iterator in_op = name_operator_.find(in_name);
683	    if (in_op == name_operator_.end()) {
684	      GELOGE(PARAM_INVALID, "[Get][Inputs] Model assigned input node name: %s cannot find in graph.", in_name.c_str());
685	      REPORT_INNER_ERR_MSG("E19999", "Model assigned input node name: %s cannot find in graph.", in_name.c_str());
686	      return PARAM_INVALID;
687	    }
688	    input_ops.emplace_back(in_op->second);
689	    GELOGI("Model assigned input node name: %s", ParserUtils::GetOperatorName(in_op->second).c_str());
690	  }
691	  return SUCCESS;
692	}
