694	Status OnnxModelParser::AddNoInputNodesToGraph(ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
695	  auto compute_graph = ge::GraphUtilsEx::GetComputeGraph(graph);
696	  GE_CHECK_NOTNULL(compute_graph);
697	  for (int i = 0; i < onnx_graph.node_size(); i++) {
698	    const auto &node = onnx_graph.node(i);
699	    if (node.input_size() != 0) {
700	      continue;
701	    }
702	    if (compute_graph->FindNode(node.name()) != nullptr) {
703	      continue;
704	    }
705	    const auto iter = name_operator_.find(node.name());
706	    if (iter == name_operator_.end()) {
707	      continue;
708	    }
709	    (void)graph.AddNodeByOp(iter->second);
710	  }
711	  return SUCCESS;
712	}
