724	Status OnnxModelParser::GetGraphOutputs(std::vector<std::pair<Operator, std::vector<size_t>>> &output_ops,
725	                                        ParserUtils::OutputMapping &out_tensor_to_nodes) {
726	  for (auto output_name : output_node_names_) {
727	    std::map<std::string, std::vector<std::pair<std::string, int>>>::const_iterator itr =
728	        outputs_map_.find(output_name);
729	    if (itr == outputs_map_.end()) {
730	      GELOGE(PARAM_INVALID, "[Get][Outputs] Cannot find output:%s in graph.", output_name.c_str());
731	      REPORT_INNER_ERR_MSG("E19999", "[Get][Outputs] Cannot find output:%s in graph.", output_name.c_str());
732	      return PARAM_INVALID;
733	    }
734	
735	    std::vector<std::pair<std::string, int>> node_names_indexes = itr->second;
736	    for (const auto &node_name_index : node_names_indexes) {
737	      auto node_name = node_name_index.first;
738	      std::map<std::string, ge::Operator>::const_iterator out_op_itr = name_operator_.find(node_name);
739	      if (out_op_itr == name_operator_.end()) {
740	        GELOGE(PARAM_INVALID, "[Get][Operator] Cannot find operator: %s in graph.", node_name.c_str());
741	        REPORT_INNER_ERR_MSG("E19999", "Cannot find operator: %s in graph.", node_name.c_str());
742	        return PARAM_INVALID;
743	      }
744	      int index = node_name_index.second;
745	      output_ops.emplace_back(out_op_itr->second, vector<size_t>{static_cast<size_t>(index)});
746	      out_tensor_to_nodes[output_name] = std::make_pair(node_name, index);
747	      GELOGI("Out node index %d, node:%s", index, node_name.c_str());
748	    }
749	  }
750	  return SUCCESS;
751	}
