771	Status OnnxModelParser::SetExternalPath(const char *file, ge::onnx::ModelProto &onnx_model) const {
772	  std::string real_path = ge::parser::RealPath(file);
773	  const size_t file_len = real_path.length();
774	  std::unique_ptr<char[]> tmp_file(new (std::nothrow) char[file_len + 1U]);
775	  GE_CHECK_NOTNULL(tmp_file);
776	
777	  const auto ret = strncpy_s(tmp_file.get(), file_len + 1U, real_path.c_str(), file_len);
778	  if (ret != EN_OK) {
779	    REPORT_INNER_ERR_MSG("E19999", "strncpy_s failed, src=%s, dst=%p, src_len=%zu, dst_len=%zu, ret=%d.",
780	                         real_path.c_str(), static_cast<void *>(tmp_file.get()), file_len, file_len + 1U, ret);
781	    GELOGE(FAILED, "strncpy_s failed, src=%s, dst=%p, src_len=%zu, dst_len=%zu.", real_path.c_str(),
782	           static_cast<void *>(tmp_file.get()), file_len, file_len + 1U);
783	    return FAILED;
784	  }
785	  const char *const dir = mmDirName(tmp_file.get());
786	  GE_CHECK_NOTNULL(dir);
787	
788	  const ge::onnx::GraphProto &onnx_graph = onnx_model.graph();
789	  for (int32_t i = 0; i < onnx_graph.initializer_size(); ++i) {
790	    const ge::onnx::TensorProto &initializer_tensor = onnx_graph.initializer(i);
791	    if (initializer_tensor.data_location() != ge::onnx::TensorProto_DataLocation_EXTERNAL) {
792	      continue;
793	    }
794	    for (int32_t j = 0; j < initializer_tensor.external_data_size(); ++j) {
795	      ge::onnx::StringStringEntryProto &string_proto =
796	          const_cast<ge::onnx::StringStringEntryProto &>(initializer_tensor.external_data(j));
797	      if (string_proto.key() != kLocation) {
798	        continue;
799	      }
800	      const std::string &file_name = string_proto.value();
801	      const std::string new_file = std::string(dir) + MMPA_PATH_SEPARATOR_STR + file_name;
802	      GELOGD("[%s] is external data. concat dir[%s] and file_name[%s], new_file[%s]", initializer_tensor.name().c_str(),
803	             dir, file_name.c_str(), new_file.c_str());
804	      string_proto.set_value(new_file);
805	    }
806	  }
807	
808	  for (int32_t i = 0; i < onnx_graph.node_size(); ++i) {
809	    const ge::onnx::NodeProto &node_proto = onnx_graph.node(i);
810	    if (node_proto.op_type() != kOpTypeConstant) {
811	      continue;
812	    }
813	    for (int32_t j = 0; j < node_proto.attribute_size(); ++j) {
814	      const ge::onnx::AttributeProto &attribute_proto = node_proto.attribute(j);
815	      if (attribute_proto.name() != kAttrNameValue) {
816	        continue;
817	      }
818	      const ge::onnx::TensorProto &tensor_proto = attribute_proto.t();
819	      if (tensor_proto.data_location() != ge::onnx::TensorProto_DataLocation_EXTERNAL) {
820	        continue;
821	      }
822	      for (int32_t k = 0; k < tensor_proto.external_data_size(); ++k) {
823	        ge::onnx::StringStringEntryProto &string_proto =
824	            const_cast<ge::onnx::StringStringEntryProto &>(tensor_proto.external_data(k));
825	        if (string_proto.key() != kLocation) {
826	          continue;
827	        }
828	        const std::string &file_name = string_proto.value();
829	        const std::string new_file = std::string(dir) + MMPA_PATH_SEPARATOR_STR + file_name;
830	        GELOGD("[%s] is external data. concat dir[%s] and file_name[%s], new_file[%s]", node_proto.name().c_str(), dir,
831	               file_name.c_str(), new_file.c_str());
832	        string_proto.set_value(new_file);
833	      }
834	    }
835	  }
836	  return SUCCESS;
837	}
