859	Status OnnxModelParser::AdaptAndFindAllOnnxGraph(
860	    ge::onnx::GraphProto &root_onnx_graph, std::map<std::string, ge::onnx::GraphProto *> &name_to_onnx_graph) const {
861	  std::queue<ge::onnx::GraphProto *> onnx_graph_tasks;
862	  int index = 0;
863	  onnx_graph_tasks.push(&root_onnx_graph);
864	
865	  while (!onnx_graph_tasks.empty()) {
866	    ge::onnx::GraphProto *onnx_graph = onnx_graph_tasks.front();
867	    onnx_graph_tasks.pop();
868	    std::string graph_name;
869	    for (const auto &graph_iter : name_to_onnx_graph) {
870	      if (graph_iter.second == onnx_graph) {
871	        graph_name = graph_iter.first;
872	        break;
873	      }
874	    }
875	
876	    for (int i = 0; i < onnx_graph->node_size(); i++) {
877	      ge::onnx::NodeProto *node_proto = onnx_graph->mutable_node(i);
878	      if (node_proto->name().empty()) {
879	        std::string node_name = node_proto->op_type() + "_" + to_string(index++);
880	        node_proto->set_name(node_name);
881	      }
882	      GELOGD("adapt op name:%s, op type:%s", node_proto->name().c_str(), node_proto->op_type().c_str());
883	
884	      SubgraphAdapterFactory *factory = SubgraphAdapterFactory::Instance();
885	      GE_CHECK_NOTNULL(factory);
886	      std::shared_ptr<SubgraphAdapter> subgraph_adapter = factory->CreateSubgraphAdapter(node_proto->op_type());
887	      if (subgraph_adapter == nullptr) {
888	        GELOGD("Do not need adapt subgraph, op type:%s", node_proto->op_type().c_str());
889	        continue;
890	      }
891	      std::vector<ge::onnx::GraphProto *> onnx_graphs;
892	      std::map<std::string, ge::onnx::GraphProto *> name_to_onnx_subgraph;
893	      if (subgraph_adapter->AdaptAndFindAllSubgraphs(node_proto, onnx_graphs, name_to_onnx_subgraph, graph_name) !=
894	          SUCCESS) {
895	        GELOGE(FAILED, "[Adapt][Subgraph] adapt subgraph of node:%s failed.", node_proto->name().c_str());
896	        REPORT_INNER_ERR_MSG("E19999", "adapt subgraph of node:%s failed.", node_proto->name().c_str());
897	        return FAILED;
898	      }
899	
900	      for (const auto &sub_onnx_graph : onnx_graphs) {
901	        onnx_graph_tasks.push(sub_onnx_graph);
902	      }
903	      for (const auto &itr : name_to_onnx_subgraph) {
904	        name_to_onnx_graph.emplace(itr.first, itr.second);
905	      }
906	    }
907	  }
908	  return SUCCESS;
909	}
