911	Status OnnxModelParser::ModelParseToGraph(const ge::onnx::ModelProto &onnx_model, ge::Graph &root_graph) {
912	  if (!onnx_model.has_graph()) {
913	    REPORT_PREDEFINED_ERR_MSG("E16004", std::vector<const char *>({}), std::vector<const char *>({}));
914	    GELOGE(PARAM_INVALID, "Onnx model do not has graph.");
915	    return FAILED;
916	  }
917	  std::map<std::string, ge::onnx::GraphProto *> name_to_onnx_graph;
918	  std::deque<ParseArg> tasks;
919	  ge::onnx::GraphProto root_onnx_graph = onnx_model.graph();
920	
921	  auto ret = AdaptAndFindAllOnnxGraph(root_onnx_graph, name_to_onnx_graph);
922	  if (ret != SUCCESS) {
923	    GELOGE(FAILED, "[AdaptAndFind][OnnxGraph]adapt and find all onnx graph failed, root graph:%s.",
924	           root_onnx_graph.name().c_str());
925	    return FAILED;
926	  }
927	
928	  auto opset_import = onnx_model.opset_import();
929	  for (auto it : opset_import) {
930	    std::string domain = it.domain().empty() ? "ai.onnx" : it.domain();
931	    domain_verseion_[domain] = it.version();
932	    GELOGI("Domain:[%s], Version:[%ld].", domain.c_str(), it.version());
933	  }
934	  std::string root_graph_name =
935	      ParserUtils::GetGraphName(root_graph).empty() ? "default_graph" : ParserUtils::GetGraphName(root_graph);
936	  tasks.push_back({&root_onnx_graph, nullptr, root_graph_name, 0});
937	
938	  while (!tasks.empty()) {
939	    ParseArg arg = tasks.front();
940	    tasks.pop_front();
941	    bool is_subgraph = (arg.parent_node != nullptr) ? true : false;
942	
943	    if (arg.onnx_graph == nullptr) {
944	      std::map<std::string, ge::onnx::GraphProto *>::const_iterator itr = name_to_onnx_graph.find(arg.graph_name);
945	      if (itr == name_to_onnx_graph.end()) {
946	        GELOGI("Graph: %s is subgraph from plugin, no need parser", arg.graph_name.c_str());
947	        continue;
948	      }
949	      arg.onnx_graph = itr->second;
950	    }
951	
952	    ge::onnx::GraphProto *onnx_graph = arg.onnx_graph;
953	    ge::Graph tmp_graph(arg.graph_name.c_str());
954	    ret = ModelParseToGraphImpl(is_subgraph, *onnx_graph, tmp_graph);
955	    if (ret != SUCCESS) {
956	      GELOGE(ret, "[Parse][Model] Model parse to graph failed, graph name:%s.", arg.graph_name.c_str());
957	      REPORT_INNER_ERR_MSG("E19999", "Model parse to graph failed, graph name:%s.", arg.graph_name.c_str());
958	      return ret;
959	    }
960	    // To get the result for root graph
961	    if (!is_subgraph) {
962	      root_graph = tmp_graph;
963	    }
964	
965	    ge::ComputeGraphPtr cur_compute_graph = ge::GraphUtilsEx::GetComputeGraph(tmp_graph);
966	    if ((ge::GetParserContext().run_mode == ge::ONLY_PRE_CHECK) && (cur_compute_graph == nullptr)) {
967	      GELOGD("Only prechecker.");
968	      return SUCCESS;
969	    }
970	    GE_CHECK_NOTNULL(cur_compute_graph);
971	
972	    ret = PostOpProcessForSubgraph(arg, cur_compute_graph);
973	    if (ret != SUCCESS) {
974	      GELOGE(ret, "[PostProcess][Subgraph]Post Op for subgraph:%s failed.", cur_compute_graph->GetName().c_str());
975	      REPORT_INNER_ERR_MSG("E19999", "Post Op for subgraph:%s failed.", cur_compute_graph->GetName().c_str());
976	      return ret;
977	    }
978	
979	    ret = BuildLinkForChildAndParentGraph(cur_compute_graph, arg);
980	    if (ret != SUCCESS) {
981	      GELOGE(ret, "[BuildLink][Graph] Build link for child graph:%s and parent graph failed.",
982	             cur_compute_graph->GetName().c_str());
983	      REPORT_INNER_ERR_MSG("E19999", "Build link for child graph:%s and parent graph failed.",
984	                           cur_compute_graph->GetName().c_str());
985	      return ret;
986	    }
987	
988	    ret = GenSubgraphParseTasks(cur_compute_graph, tasks);
989	    if (ret != SUCCESS) {
990	      GELOGE(ret, "[Generate][Task] Failed to gen tasks on graph %s for next iteration",
991	             cur_compute_graph->GetName().c_str());
992	      REPORT_INNER_ERR_MSG("E19999", "Failed to gen tasks on graph %s for next iteration",
993	                           cur_compute_graph->GetName().c_str());
994	      return ret;
995	    }
996	  }
997	  UpdateDataFormat(root_graph);
998	  return SUCCESS;
999	}
