1001	Status OnnxModelParser::ModelParseToGraphImpl(bool is_subgraph, ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
1002	  ClearMembers();
1003	  GE_RETURN_WITH_LOG_IF_ERROR(ProtoTypePassManager::Instance().Run(&onnx_graph, domi::ONNX),
1004	                              "Run ProtoType Pass Failed");
1005	  // 1. Get all initializer.
1006	  std::map<std::string, ge::onnx::TensorProto> initializer_name_tensor;
1007	  for (int i = 0; i < onnx_graph.initializer_size(); i++) {
1008	    ge::onnx::TensorProto initializer_tensor = onnx_graph.initializer(i);
1009	    if (!initializer_tensor.name().empty()) {
1010	      initializer_name_tensor[initializer_tensor.name()] = initializer_tensor;
1011	      GELOGI("Initializer name:[%s].", initializer_tensor.name().c_str());
1012	    }
1013	  }
1014	
1015	  // 2. Parse Input from graph.
1016	  GELOGI("The size of initializer_name_tensor is %zu ", initializer_name_tensor.size());
1017	
1018	  Status ret = ParseInput(initializer_name_tensor, is_subgraph, onnx_graph);
1019	  if (ret != SUCCESS) {
1020	    GELOGE(ret, "[Parse][Input] for onnx failed.");
1021	    return ret;
1022	  }
1023	  GELOGI("The size of initializer_name_tensor is %zu after ParseInput", initializer_name_tensor.size());
1024	
1025	  // 3. Parse Constant(initializer) from graph.
1026	  ret = ParseInitializer(onnx_graph, initializer_name_tensor);
1027	  if (ret != SUCCESS) {
1028	    GELOGE(ret, "[Parse][Initializer] for onnx failed.");
1029	    return ret;
1030	  }
1031	
1032	  // 4. Get all output name form origin graph
1033	  ret = ParseOutput(onnx_graph);
1034	  if (ret != SUCCESS) {
1035	    GELOGE(ret, "[Parse][Output] Parse output for onnx failed.");
1036	    return ret;
1037	  }
1038	
1039	  // 5. Update node name for node do not has name, update const op type
1040	  UpdateNodeNameAndOpType(onnx_graph);
1041	
1042	  // 6 Precheck.
1043	  ret = Prechecker(onnx_graph);
1044	  bool is_precheck_failed = (ret != SUCCESS) || (ge::PreChecker::Instance().HasError());
1045	  if (is_precheck_failed) {
1046	    GELOGE(FAILED, "[Invoke][Prechecker] failed.");
1047	    return FAILED;
1048	  }
1049	
1050	  if (ge::GetParserContext().run_mode == ge::ONLY_PRE_CHECK) {
1051	    GELOGI("Only prechecker.");
1052	    return SUCCESS;
1053	  }
1054	
1055	  // 7. Construct all operator and input output tensor relation.
1056	  ret = ParseAllNodeProto(onnx_graph, graph);
1057	  if (ret != SUCCESS) {
1058	    GELOGE(ret, "[Parse][AllNodeProto] failed.");
1059	    return ret;
1060	  }
1061	
1062	  std::vector<AscendString> op_names;
1063	  graph.GetAllOpName(op_names);
1064	  GELOGI("After trans node to operator, graph has the size of operator is %zu.", op_names.size());
1065	
1066	  // 8. Set all operator input.
1067	  ret = SetOperatorInputs();
1068	  if (ret != SUCCESS) {
1069	    GELOGE(ret, "[Set][OperatorInputs] failed.");
1070	    return ret;
1071	  }
1072	
1073	  // 9. Construct graph.
1074	  std::vector<ge::Operator> input_ops;
1075	  ret = GetGraphInputs(onnx_graph, input_ops);
1076	  if (ret != SUCCESS) {
1077	    GELOGE(ret, "[Get][GraphInputs] failed.");
1078	    return ret;
1079	  }
1080	  std::string topo_sorting_mode_str;
1081	  ge::GetContext().GetOption(ge::OPTION_TOPOSORTING_MODE, topo_sorting_mode_str);
1082	  const int32_t base = 10;
1083	  auto topo_sorting_mode =
1084	      topo_sorting_mode_str.empty()
1085	          ? TopoSortingMode::kDFS
1086	          : static_cast<TopoSortingMode>(std::strtol(topo_sorting_mode_str.c_str(), nullptr, base));
1087	  if (topo_sorting_mode == TopoSortingMode::kStableRDFS) {
1088	    std::vector<ge::Operator> ops;
1089	    GE_ASSERT_SUCCESS(GetAllGraphNodes(onnx_graph, ops));
1090	    GE_ASSERT_SUCCESS(GraphUtilsEx::CreateGraphFromOperatorWithStableTopo(graph, ops));
1091	  } else {
1092	    graph.SetInputs(input_ops);
1093	    GE_ASSERT_SUCCESS(AddNoInputNodesToGraph(onnx_graph, graph));
1094	  }
1095	
1096	  // 10. Get output info and set outputs for subgraph
1097	  std::vector<std::pair<Operator, std::vector<size_t>>> output_ops;
1098	  ParserUtils::OutputMapping out_tensor_to_nodes;
1099	  ret = GetGraphOutputs(output_ops, out_tensor_to_nodes);
1100	  if (ret != SUCCESS) {
1101	    GELOGE(ret, "[Get][Outputs] failed.");
1102	    return ret;
1103	  }
1104	  // root graph needn't set outputs.
1105	  if (is_subgraph) {
1106	    graph.SetOutputs(output_ops);
1107	  }
1108	
1109	  // 11. Expand node to graph if need
1110	  ParserUtils::OutputMapping final_output_nodes;
1111	  GE_RETURN_IF_ERROR(ParserUtils::ExpandOneToManyGraph(graph, final_output_nodes));
1112	
1113	  // 12. Set outputs info in ParserContext for root graph
1114	  if (!is_subgraph) {
1115	    ret = SetOutputsInfo(final_output_nodes, out_tensor_to_nodes);
1116	    if (ret != SUCCESS) {
1117	      GELOGE(ret, "[Set][OutputsInfo] Graph:%s.", ParserUtils::GetGraphName(graph).c_str());
1118	      return ret;
1119	    }
1120	  }
1121	
1122	  GELOGI("Onnx model parser success.");
1123	  return SUCCESS;
1124	}
