1156	Status OnnxModelParser::ToJson(const char *model_file, const char *json_file) {
1157	  if (model_file == nullptr) {
1158	    REPORT_PREDEFINED_ERR_MSG("E13000", std::vector<const char *>({"path", "errmsg"}),
1159	                              std::vector<const char *>({"", "param model file is nullptr"}));
1160	    GELOGE(FAILED, "[Check][Param] Model file is nullptr.");
1161	    return FAILED;
1162	  }
1163	  if (json_file == nullptr) {
1164	    REPORT_PREDEFINED_ERR_MSG("E13000", std::vector<const char *>({"path", "errmsg"}),
1165	                              std::vector<const char *>({"", "param json file is nullptr"}));
1166	    GELOGE(FAILED, "[Check][Param]Json file is nullptr.");
1167	    return FAILED;
1168	  }
1169	
1170	  ge::onnx::ModelProto onnx_model;
1171	  GE_RETURN_WITH_LOG_IF_FALSE(ge::parser::ReadProtoFromBinaryFile(model_file, &onnx_model),
1172	                              "[Invoke][ReadProtoFromBinaryFile] failed, file:%s.", model_file);
1173	  ge::onnx::GraphProto graph_proto = onnx_model.graph();
1174	  nlohmann::json j;
1175	  ge::Pb2Json::Message2Json(graph_proto, std::set<std::string>(), j, true);
1176	  return ge::parser::ModelSaver::SaveJsonToFile(json_file, j);
1177	}
