1183	void OnnxModelParser::UpdateDataFormat(ge::Graph &graph) const {
1184	  for (GNode &gn : graph.GetDirectNode()) {
1185	    AscendString type;
1186	    (void)gn.GetType(type);
1187	    if (type != parser::DATA) {
1188	      continue;
1189	    }
1190	    TensorDesc in_desc;
1191	    gn.GetInputDesc(0, in_desc);
1192	    ge::Format ge_format = TypeUtilsInner::DomiFormatToFormat(GetParserContext().format);
1193	    in_desc.SetOriginFormat(ge_format);
1194	    in_desc.SetFormat(ge_format);
1195	    gn.UpdateInputDesc(0, in_desc);
1196	
1197	    TensorDesc out_desc;
1198	    gn.GetOutputDesc(0, out_desc);
1199	    out_desc.SetOriginFormat(ge_format);
1200	    out_desc.SetFormat(ge_format);
1201	    gn.UpdateOutputDesc(0, out_desc);
1202	  }
1203	  GELOGD("Update data format success.");
