1207	Status OnnxModelParser::SetOutputsInfo(const ParserUtils::OutputMapping &final_output_nodes,
1208	                                       const ParserUtils::OutputMapping &tensor_to_nodes) {
1209	  // 记录一对多转换场景中原算子名称到子图实际输出名称的映射关系，传递给外部OMG流程用于更新输出算子相关信息（如datatype）
1210	  auto &final_out_nodes_map = ge::GetParserContext().final_out_nodes_map;
1211	  for (const auto &node_info : final_output_nodes) {
1212	    (void)final_out_nodes_map.emplace(node_info.first, node_info.second);
1213	  }
1214	
1215	  auto &user_specified_nodes = ge::GetParserContext().user_out_nodes;
1216	  if (!user_specified_nodes.empty()) {
1217	    GELOGI("User specified the output nodes with node_name and index.");
1218	    for (auto &output_node_info : user_specified_nodes) {
1219	      ParserUtils::UpdateOutputNodeInfo(final_output_nodes, output_node_info);
1220	    }
1221	    return SUCCESS;
1222	  }
1223	
1224	  auto final_tensor_to_nodes = tensor_to_nodes;
1225	  ParserUtils::UpdateOutputCtx(final_output_nodes, final_tensor_to_nodes);
1226	  auto &user_specified_tensors = ge::GetParserContext().user_out_tensors;
1227	  auto &output_tensor_names = ge::GetParserContext().out_tensor_names;
1228	  output_tensor_names.clear();
1229	  if (!user_specified_tensors.empty()) {
1230	    for (auto &tensor_name : user_specified_tensors) {
1231	      auto iter = final_tensor_to_nodes.find(tensor_name);
1232	      if (iter != final_tensor_to_nodes.end()) {
1233	        user_specified_nodes.emplace_back(iter->second);
1234	        output_tensor_names.emplace_back(tensor_name);
1235	        GELOGI("[UserSpecified]Add network output node[%s], index[%d], tensor name[%s].", iter->second.first.c_str(),
1236	               iter->second.second, tensor_name.c_str());
1237	      } else {
1238	        REPORT_INNER_ERR_MSG("E19999", "User specified tensor[%s] is not output of graph.", tensor_name.c_str());
1239	        GELOGE(FAILED, "[Set][OutputsInfo]User specified tensor[%s] is not output of graph.", tensor_name.c_str());
1240	        return FAILED;
1241	      }
1242	    }
1243	    return SUCCESS;
1244	  }
1245	
1246	  // for default output
1247	  auto &default_out_nodes = ge::GetParserContext().default_out_nodes;
1248	  for (auto &tensor_name : output_node_names_) {
1249	    auto &output_node_info = final_tensor_to_nodes[tensor_name];
1250	    default_out_nodes.emplace_back(output_node_info);
1251	    output_tensor_names.emplace_back(tensor_name);
1252	    GELOGI("[Default]Add network output node[%s], index[%d], tensor name[%s].", output_node_info.first.c_str(),
1253	           output_node_info.second, tensor_name.c_str());
1254	  }
1255	  return SUCCESS;
1256	}
