namespace ge {
graphStatus PrepareBeforeParse(AclGraphParserUtil &acl_graph_parse_util,
                               const std::map<AscendString, AscendString> &parser_params, ge::Graph &graph,
                               std::shared_ptr<domi::ModelParser> &model_parser) {
  GetParserContext().type = domi::ONNX;
  Status init_ret = ge::SUCCESS;
  static std::once_flag flag;
  std::call_once(flag, [&init_ret, &acl_graph_parse_util]() {
    std::map<string, string> options;
    options.insert(std::pair<string, string>(string(ge::FRAMEWORK_TYPE), to_string(domi::ONNX)));
    init_ret = acl_graph_parse_util.AclParserInitialize(options);
  });

  if (init_ret != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "AclParserInitialize failed.");
    GELOGE(ge::FAILED, "[Init][AclParser] failed.");
    return ge::FAILED;
  }

  string output_name;
  if (acl_graph_parse_util.ParseParamsBeforeGraph(parser_params, output_name) != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "ParseParamsBeforeGraph failed.");
    GELOGE(ge::FAILED, "[Parser][Params] before graph failed.");
    return ge::FAILED;
  }
  // Create an empty computegraph
  string graph_name = output_name.empty() ? "tmpGraph" : output_name;
  ge::ComputeGraphPtr compute_graph = ge::parser::MakeShared<ge::ComputeGraph>(graph_name);
  GE_CHECK_NOTNULL(compute_graph);

  graph = ge::GraphUtilsEx::CreateGraphFromComputeGraph(compute_graph);
  model_parser = domi::ModelParserFactory::Instance()->CreateModelParser(domi::ONNX);
  GE_CHECK_NOTNULL(model_parser);
  return ge::SUCCESS;
}

graphStatus HandleAfterParse(AclGraphParserUtil &acl_graph_parse_util,
                             const std::map<AscendString, AscendString> &parser_params, ge::Graph &graph) {
  if (acl_graph_parse_util.ParseParamsAfterGraph(graph, parser_params) != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "ParseParamsAfterGraph failed.");
    GELOGE(ge::FAILED, "[Parser][Params] after graph failed.");
    return ge::FAILED;
  }

  if (acl_graph_parse_util.SetOutputNodeInfo(graph, parser_params) != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "Set graph default output node failed.");
    GELOGE(ge::FAILED, "[Update][NodeInfo] Set graph %s default output node failed.",
           ParserUtils::GetGraphName(graph).c_str());
    return ge::FAILED;
  }
  return ge::SUCCESS;
}

graphStatus aclgrphParseONNX(const char *model_file, const std::map<AscendString, AscendString> &parser_params,
                             ge::Graph &graph) {
  PARSER_TIMESTAMP_START(aclgrphParseONNX);
  GE_CHECK_NOTNULL(model_file);
  // load custom plugin so and proto
  AclGraphParserUtil acl_graph_parse_util;
  std::shared_ptr<domi::ModelParser> model_parser;

  if (PrepareBeforeParse(acl_graph_parse_util, parser_params, graph, model_parser) != ge::SUCCESS) {
    GELOGE(ge::FAILED, "[Invoke][PrepareBeforeParse] failed.");
    return ge::FAILED;
  }

  GE_CHECK_NOTNULL(model_parser);
  // parse onnx model_file to GE graph
  ge::graphStatus ret = model_parser->Parse(model_file, graph);
  if (ret != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "parse modelfile %s failed, graph:%s", model_file,
                         ParserUtils::GetGraphName(graph).c_str());
    GELOGE(ret, "[Parse][ModelFile] %s failed, graph %s.", model_file, ParserUtils::GetGraphName(graph).c_str());
    return ge::FAILED;
  }
  GELOGI("Parse graph %s success.", ParserUtils::GetGraphName(graph).c_str());

  if (HandleAfterParse(acl_graph_parse_util, parser_params, graph) != ge::SUCCESS) {
    GELOGE(ge::FAILED, "[Invoke][HandleAfterParse] failed.");
    return ge::FAILED;
  }
  std::string trace_log = "call aclgrphParseONNX to parse graph " + ParserUtils::GetGraphName(graph);
  PARSER_TIMESTAMP_EVENT_END(aclgrphParseONNX, trace_log.c_str());
  return ge::SUCCESS;
}

graphStatus aclgrphParseONNXFromMem(const char *buffer, size_t size,
                                    const std::map<AscendString, AscendString> &parser_params, ge::Graph &graph) {
  GE_CHECK_NOTNULL(buffer);
  // load custom plugin so and proto
  AclGraphParserUtil acl_graph_parse_util;
  std::shared_ptr<domi::ModelParser> model_parser;

  if (PrepareBeforeParse(acl_graph_parse_util, parser_params, graph, model_parser) != ge::SUCCESS) {
    GELOGE(ge::FAILED, "[Invoke][PrepareBeforeParse] failed.");
    return ge::FAILED;
  }

  // parse caffe model_file to GE graph
  ge::graphStatus ret = model_parser->ParseFromMemory(buffer, static_cast<uint32_t>(size), graph);
  if (ret != ge::SUCCESS) {
    REPORT_INNER_ERR_MSG("E19999", "ParseFromMemory failed");
    GELOGE(ret, "[Parser][Graph] %s failed.", ParserUtils::GetGraphName(graph).c_str());
    return ge::FAILED;
  }
  GELOGI("Parse graph %s success.", ParserUtils::GetGraphName(graph).c_str());

  if (HandleAfterParse(acl_graph_parse_util, parser_params, graph) != ge::SUCCESS) {
    GELOGE(ge::FAILED, "[Invoke][HandleAfterParse] failed.");
    return ge::FAILED;
  }
  GELOGI("Call aclgrphParse to parse graph %s success.", ParserUtils::GetGraphName(graph).c_str());
  return ge::SUCCESS;
}
}  // namespace ge

namespace ge {
namespace {
const std::map<std::string, std::string> kOnnxOpMap = {{ge::kOpTypeInput, ge::parser::DATA},
                                                       {ge::kOpTypeConstant, ge::parser::CONSTANT},
                                                       {ge::kFileConstant, ge::parser::FILECONSTANT}};
const int64_t kDimValue = 1;

struct ParseArg {
  ge::onnx::GraphProto *onnx_graph;
  ge::NodePtr parent_node;
  std::string graph_name;
  uint32_t subgraph_index;
};

Status GenSubgraphParseTasks(const ge::ComputeGraphPtr &parent_graph, std::deque<ParseArg> &args) {
  GELOGI("Generate subgraph parse tasks start");
  for (auto &node : parent_graph->GetDirectNode()) {
    auto op_desc = node->GetOpDesc();
    GE_CHECK_NOTNULL(op_desc);
    for (const auto &subgraph_name_to_index : op_desc->GetSubgraphNameIndexes()) {
      auto i = subgraph_name_to_index.second;
      auto subgraph_iname = subgraph_name_to_index.first;
      if (subgraph_iname.empty()) {
        GELOGW("The subgraph index %u of node %s is empty", i, node->GetName().c_str());
        continue;
      }

      // change the graph name to ensure it is unique in GE
      std::string unique_subgraph_name;
      OnnxUtil::GenUniqueSubgraphName(i, subgraph_iname, node->GetName(), unique_subgraph_name);

      GELOGD("Add subgraph parse task to the queue, node %s, index %u, subgraph instance name %s",
             node->GetName().c_str(), i, unique_subgraph_name.c_str());
      args.push_back({nullptr, node, unique_subgraph_name, i});
    }
  }
  GELOGI("Generate subgraph parse tasks end");
  return SUCCESS;
}

Status BuildLinkForChildAndParentGraph(const ge::ComputeGraphPtr &sub_graph, const ParseArg &arg) {
  if (arg.parent_node == nullptr) {
    return SUCCESS;
  }
  auto parent_node = arg.parent_node;
  auto index = arg.subgraph_index;
  auto ret = ge::NodeUtils::SetSubgraph(*parent_node, index, sub_graph);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Set][Subgraph] Failed to set subgraph %s to node %s index %u", sub_graph->GetName().c_str(),
           parent_node->GetName().c_str(), index);
    REPORT_INNER_ERR_MSG("E19999", "Failed to set subgraph %s to node %s index %u", sub_graph->GetName().c_str(),
                         parent_node->GetName().c_str(), index);
    return ret;
  }
  return SUCCESS;
}

Status PostOpProcessForSubgraph(const ParseArg &arg, ge::ComputeGraphPtr sub_graph) {
  if (arg.parent_node == nullptr) {
    return SUCCESS;
  }
  std::string op_type = arg.parent_node->GetType();
  std::string op_name = arg.parent_node->GetName();
  domi::ParseSubgraphFuncV2 parse_func_v2 = nullptr;
  auto post_func = domi::OpRegistry::Instance()->GetParseSubgraphPostFunc(op_type, domi::ONNX);
  if (post_func == nullptr) {
    GELOGW("The subgraph post func for node %s type %s is null", op_name.c_str(), op_type.c_str());
    if (domi::OpRegistry::Instance()->GetParseSubgraphPostFunc(op_type, domi::ONNX, parse_func_v2) != SUCCESS ||
        parse_func_v2 == nullptr) {
      GELOGW("The subgraph post func v2 for node %s type %s is null", op_name.c_str(), op_type.c_str());
      return SUCCESS;
    }
  }

  GELOGD("Post process for node %s with type %s in subgraph %s ", arg.graph_name.c_str(),
         arg.parent_node->GetType().c_str(), arg.parent_node->GetName().c_str());

  // Refresh node_name in subgraph
  for (const ge::NodePtr &node : sub_graph->GetDirectNode()) {
    if (node->GetOpDesc() == nullptr) {
      continue;
    }
    node->GetOpDesc()->SetName(OnnxUtil::GenUniqueNodeName(sub_graph->GetName(), node->GetName()));
  }

  auto graph = ge::GraphUtilsEx::CreateGraphFromComputeGraph(sub_graph);
  Status ret = FAILED;
  if (post_func != nullptr) {
    ret = post_func(arg.graph_name, graph);
  } else if (parse_func_v2 != nullptr) {
    ret = parse_func_v2(arg.graph_name.c_str(), graph);
  }
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[PostProcess][Subgraph]Failed to post-process subgraph %s on node %s type %s",
           arg.graph_name.c_str(), arg.parent_node->GetName().c_str(), arg.parent_node->GetType().c_str());
    REPORT_INNER_ERR_MSG("E19999", "Failed to post-process subgraph %s on node %s type %s", arg.graph_name.c_str(),
                         arg.parent_node->GetName().c_str(), arg.parent_node->GetType().c_str());
    return FAILED;
  }
  return SUCCESS;
}
}  // namespace

Status OnnxModelParser::ParseOutput(ge::onnx::GraphProto &onnx_graph) {
  if (onnx_graph.output_size() == 0) {
    GELOGE(FAILED, "[Parse][Output] Onnx graph:%s has zero output", onnx_graph.name().c_str());
    REPORT_PREDEFINED_ERR_MSG("E16001", std::vector<const char_t *>({"value"}),
                              std::vector<const char_t *>({"output"}));
    return FAILED;
  }

  // get output value info map
  for (int i = 0; i < onnx_graph.output_size(); i++) {
    ge::onnx::ValueInfoProto value_info = onnx_graph.output(i);
    GELOGI("The index of %d output name : %s.", i, value_info.name().c_str());
    output_node_names_.emplace_back(value_info.name());
  }
  return SUCCESS;
}

Status OnnxModelParser::ParseInput(const std::map<std::string, ge::onnx::TensorProto> &initializer_name_tensor,
                                   bool is_subgraph, ge::onnx::GraphProto &onnx_graph) {
  if (!is_subgraph && onnx_graph.input_size() == 0) {
    GELOGE(FAILED, "[Parse][Input] Root onnx graph:%s has zero input", onnx_graph.name().c_str());
    REPORT_PREDEFINED_ERR_MSG("E16001", std::vector<const char_t *>({"value"}), std::vector<const char_t *>({"input"}));
    return FAILED;
  }

  // get input value info map
  int64_t data_index = 0;
  for (int i = 0; i < onnx_graph.input_size(); i++) {
    ge::onnx::ValueInfoProto value_info = onnx_graph.input(i);
    GELOGI("The index of %d input name : %s.", i, value_info.name().c_str());

    /// if the input is initialized by a default value found in ‘initializer’,
    /// it will be considered as a const node.
    auto initializer_iter = initializer_name_tensor.find(value_info.name());
    if (initializer_iter != initializer_name_tensor.end()) {
      continue;
    }

    ge::onnx::TensorProto tensor_tmp;
    if (value_info.has_type()) {
      const ge::onnx::TypeProto type = value_info.type();
      if (type.has_tensor_type()) {
        const ge::onnx::TypeProto_Tensor type_proto_tensor = type.tensor_type();
        int32_t elem_type = type_proto_tensor.elem_type();
        tensor_tmp.set_data_type(elem_type);
        if (type_proto_tensor.has_shape()) {
          const ge::onnx::TensorShapeProto tensor_shape = type_proto_tensor.shape();
          for (int j = 0; j < tensor_shape.dim_size(); j++) {
            const ge::onnx::TensorShapeProto_Dimension dimension = tensor_shape.dim(j);
            int64_t dim_value = -1;
            if (dimension.value_case() == kDimValue) {
              dim_value = dimension.dim_value();
            }
            tensor_tmp.add_dims(dim_value);
            GELOGI("elem_type: %d, dim_value: %ld", elem_type, dim_value);
          }
        }
      }
    }
    // Construct node for input
    ge::onnx::NodeProto *input_node = onnx_graph.add_node();
    input_node->set_name(value_info.name());
    input_node->set_op_type(ge::kOpTypeInput);
    input_node->add_output(value_info.name());
    // add tensor
    ge::onnx::AttributeProto *attribute = input_node->add_attribute();
    attribute->set_name(ge::kAttrNameInput);
    ge::onnx::TensorProto *attribute_tensor = attribute->mutable_t();
    *attribute_tensor = tensor_tmp;
    // add index
    ge::onnx::AttributeProto *attribute_index = input_node->add_attribute();
    attribute_index->set_name(ge::kAttrNameIndex);
    attribute_index->set_i(data_index++);
    // add subgraph attr
    if (is_subgraph) {
      attribute = input_node->add_attribute();
      attribute->set_name(ge::kAttrNameIsSubgraphOp);
    }
    input_node_names_.emplace_back(value_info.name());
  }
  return SUCCESS;
}

Status OnnxModelParser::ParseInitializer(ge::onnx::GraphProto &onnx_graph,
                                         std::map<std::string, ge::onnx::TensorProto> &initializer_name_tensor) const {
  // Construct const node for weight
  int index = 0;
  for (auto it : initializer_name_tensor) {
    ge::onnx::NodeProto *const_node = onnx_graph.add_node();
    std::string output_name = it.first + "_" + kInitializerKey + "_" + to_string(index++);
    const_node->set_name(output_name);
    const_node->add_output(it.first);
    ge::onnx::AttributeProto *attribute = const_node->add_attribute();
    attribute->set_name(ge::kAttrNameValue);
    ge::onnx::TensorProto *attribute_t = attribute->mutable_t();
    *attribute_t = it.second;
    if (it.second.data_location() == ge::onnx::TensorProto_DataLocation_EXTERNAL) {
      const_node->set_op_type(kFileConstant);
      GELOGD("Initializer const node [%s], the weight was stored in the file.", const_node->name().c_str());
    } else {
      const_node->set_op_type(ge::kOpTypeConstant);
      GELOGD("Initializer const node [%s].", const_node->name().c_str());
    }
  }

  return SUCCESS;
}

void OnnxModelParser::UpdateConstantOpType(ge::onnx::NodeProto *node) const {
  // If weight in file, Marker Constant(not Initializer) as file constant
  for (auto it : node->attribute()) {
    if (it.name() == ge::kAttrNameValue) {
      const ::ge::onnx::TensorProto tensor_proto = it.t();
      if (tensor_proto.data_location() == ge::onnx::TensorProto_DataLocation_EXTERNAL) {
        node->set_op_type(kFileConstant);
        GELOGD("Const node [%s], the weight was stored in the file.", node->name().c_str());
      }
      break;
    }
  }
}

void OnnxModelParser::UpdateNodeNameAndOpType(ge::onnx::GraphProto &onnx_graph) const {
  int index = 0;
  for (int i = 0; i < onnx_graph.node_size(); i++) {
    ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
    if (node->name().empty()) {
      std::string node_name = node->op_type() + "_" + to_string(index++);
      node->set_name(node_name);
    }
    if (node->op_type() == kOpTypeConstant) {
      UpdateConstantOpType(node);
    }
  }
}

Status OnnxModelParser::ConstructOriType(const ge::onnx::NodeProto *node_proto, std::string &ori_type) {
  GE_CHECK_NOTNULL(node_proto);

  ori_type = node_proto->op_type();
  if (kOnnxOpMap.find(ori_type) != kOnnxOpMap.end()) {
    return SUCCESS;
  }

  std::string domain = node_proto->domain().empty() ? "ai.onnx" : node_proto->domain();
  std::map<std::string, int64_t>::const_iterator it = domain_verseion_.find(domain);
  if (it == domain_verseion_.end()) {
    REPORT_INNER_ERR_MSG("E19999", "The opset of domain[%s] has no responding version.", domain.c_str());
    GELOGE(PARAM_INVALID, "[Check][Param]The opset of domain[%s] has no responding version.", domain.c_str());
    return PARAM_INVALID;
  }
  int64_t version = it->second;

  ori_type = domain + "::" + to_string(version) + "::" + ori_type;
  return SUCCESS;
}

Status OnnxModelParser::AdapterOpType(const ge::onnx::NodeProto *node_proto, std::string &ori_type,
                                      std::string &op_type) {
  GE_CHECK_NOTNULL(node_proto);
  ori_type = node_proto->op_type();

  auto map_it = kOnnxOpMap.find(ori_type);
  if (map_it != kOnnxOpMap.end()) {
    op_type = map_it->second;
    ori_to_om_type_[ori_type] = op_type;
    return SUCCESS;
  }

  Status ret = ConstructOriType(node_proto, ori_type);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Construct][OriType] for [%s] failed.", ori_type.c_str());
    return ret;
  }

  if (!domi::OpRegistry::Instance()->GetOmTypeByOriOpType(ori_type, op_type)) {
    REPORT_PREDEFINED_ERR_MSG("E16002", std::vector<const char *>({"optype"}),
                              std::vector<const char *>({ori_type.c_str()}));
    GELOGE(PARAM_INVALID, "[Get][OmType] according ori_type : %s failed.", ori_type.c_str());
    return PARAM_INVALID;
  }

  ori_to_om_type_[ori_type] = op_type;
  return SUCCESS;
}

Status OnnxModelParser::TransNodeToOperator(const ge::onnx::NodeProto *node_proto, ge::Operator &op,
                                            const string &op_type) const {
  GE_CHECK_NOTNULL(node_proto);
  string node_name = node_proto->name();
  op = ge::OperatorFactory::CreateOperator(node_name.c_str(), op_type.c_str());
  if (ParserUtils::GetOperatorName(op) != node_name) {
    REPORT_PREDEFINED_ERR_MSG("E10501", std::vector<const char_t *>({"opname", "optype"}),
                              std::vector<const char_t *>({node_name.c_str(), op_type.c_str()}));
    GELOGE(INTERNAL_ERROR, "[Creat][Op] IR for op[%s] optype[%s] is not registered.", node_name.c_str(),
           op_type.c_str());
    return INTERNAL_ERROR;
  }

  GELOGI("After create operator, op[%s]: type[%s] have input size: %zu, output size: %zu",
         ParserUtils::GetOperatorName(op).c_str(), ParserUtils::GetOperatorType(op).c_str(), op.GetInputsSize(),
         op.GetOutputsSize());
  return SUCCESS;
}

Status OnnxModelParser::ConstructInputOutputContext(const ge::onnx::NodeProto *node_proto) {
  GE_CHECK_NOTNULL(node_proto);

  std::string node_name = node_proto->name();
  for (int i = 0; i < node_proto->input_size(); i++) {
    std::string input_name = node_proto->input(i);
    inputs_map_[input_name].emplace_back(node_name, i);
  }

  for (int i = 0; i < node_proto->output_size(); i++) {
    std::string output_name = node_proto->output(i);
    outputs_map_[output_name].emplace_back(node_name, i);
  }

  return SUCCESS;
}

Status OnnxModelParser::SetOperatorInputs() {
  for (auto in_iter = inputs_map_.begin(); in_iter != inputs_map_.end(); in_iter++) {
    auto out_iter = outputs_map_.find(in_iter->first);
    if (out_iter == outputs_map_.end()) {
      GELOGW("Unknown input: %s:%d for node: %s, which maybe option input.", in_iter->first.c_str(),
             in_iter->second[0].second, in_iter->second[0].first.c_str());
      continue;
    }

    std::vector<std::pair<std::string, int>> &input_node_indexs = in_iter->second;
    std::vector<std::pair<std::string, int>> &output_node_indexs = out_iter->second;
    for (auto input_node_index : input_node_indexs) {
      for (auto out_node_index : output_node_indexs) {
        std::map<std::string, ge::Operator>::const_iterator input_op_iter = name_operator_.find(input_node_index.first);
        if (input_op_iter == name_operator_.end()) {
          REPORT_INNER_ERR_MSG("E19999", "Node: %s cannot find in name_operator map.", input_node_index.first.c_str());
          GELOGE(INTERNAL_ERROR, "[Check][Param] Node: %s cannot find in name_operator map.",
                 input_node_index.first.c_str());
          return INTERNAL_ERROR;
        }
        std::map<std::string, ge::Operator>::const_iterator output_op_iter = name_operator_.find(out_node_index.first);
        if (output_op_iter == name_operator_.end()) {
          REPORT_INNER_ERR_MSG("E19999", "Node: %s cannot find in name_operator map.", out_node_index.first.c_str());
          GELOGE(INTERNAL_ERROR, "[Check][Param] Node: %s cannot find in name_operator map.",
                 out_node_index.first.c_str());
          return INTERNAL_ERROR;
        }

        auto dst_op = input_op_iter->second;
        auto src_op = output_op_iter->second;
        int dst_index = input_node_index.second;
        int src_index = out_node_index.second;
        GELOGI("Start add output:%d of op:%s as input:%d of op:%s.", src_index,
               ParserUtils::GetOperatorName(src_op).c_str(), dst_index, ParserUtils::GetOperatorName(dst_op).c_str());
        auto dst_op_desc = ge::OpDescUtils::GetOpDescFromOperator(dst_op);
        GE_CHECK_NOTNULL(dst_op_desc);
        auto src_op_desc = ge::OpDescUtils::GetOpDescFromOperator(src_op);
        GE_CHECK_NOTNULL(src_op_desc);
        dst_op.SetInput(dst_op_desc->GetInputNameByIndex(dst_index).c_str(), src_op,
                        src_op_desc->GetOutputNameByIndex(src_index).c_str());
      }
    }
  }
  return SUCCESS;
}

Status OnnxModelParser::Prechecker(ge::onnx::GraphProto &onnx_graph) {
  ge::PreChecker::Instance().Clear();
  for (int i = 0; i < onnx_graph.node_size(); i++) {
    ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
    std::string ori_type;
    Status ret = ConstructOriType(node, ori_type);
    if (ret != SUCCESS) {
      GELOGE(ret, "[Construct][OriType] for [%s] failed.", ori_type.c_str());
      return ret;
    }
    GELOGI("Construct ori type : %s ", ori_type.c_str());
    if (ge::PreChecker::Instance().AddOp(node, node->name(), ori_type) != SUCCESS) {
      REPORT_INNER_ERR_MSG("E19999", "AddOp failed, node:%s", node->name().c_str());
      GELOGE(FAILED, "[Add][NodeDef] to PreChecker failed, node name: %s.", node->name().c_str());
      return FAILED;
    }
    if (ge::PreChecker::Instance().CheckName(node) != SUCCESS) {
      REPORT_INNER_ERR_MSG("E19999", "CheckName failed for node:%s", node->name().c_str());
      GELOGE(FAILED, "[Check][Name] failed, node name: %s.", node->name().c_str());
      return FAILED;
    }
    if (kOnnxOpMap.find(ori_type) == kOnnxOpMap.end()) {
      if (ge::PreChecker::Instance().CheckType(node) != SUCCESS) {
        REPORT_INNER_ERR_MSG("E19999", "CheckType failed for node:%s", node->name().c_str());
        GELOGE(FAILED, "[Check][Type] failed, node name: %s.", node->name().c_str());
        return FAILED;
      }
    }
  }
  return SUCCESS;
}

Status OnnxModelParser::ParseOpParam(const ge::onnx::NodeProto *node_proto, ge::Operator &op,
                                     std::shared_ptr<OpParser> &op_parser) const {
  GE_CHECK_NOTNULL(node_proto);
  GE_CHECK_NOTNULL(op_parser);
  std::string op_type = node_proto->op_type();

  Status status = FAILED;
  domi::ParseParamByOpFunc parse_param_func = domi::OpRegistry::Instance()->GetParseParamByOperatorFunc(op_type);
  if (parse_param_func == nullptr) {
    status = op_parser->ParseParams(node_proto, op);
  } else {
    ge::Operator op_src(node_proto->name().c_str(), op_type.c_str());
    status = Message2Operator::ParseOperatorAttrs(node_proto, 1, op_src);
    if (status != SUCCESS) {
      REPORT_INNER_ERR_MSG("E19999", "Auto mapping node:%s(%s) to operator failed", node_proto->name().c_str(),
                           op_type.c_str());
      GELOGE(status, "Node[%s] auto mapping failed.", node_proto->name().c_str());
      return status;
    }
    std::shared_ptr<ge::OnnxCustomParserAdapter> onnx_custom_op_parser =
        std::dynamic_pointer_cast<ge::OnnxCustomParserAdapter>(op_parser);
    status = onnx_custom_op_parser->ParseParams(op_src, op);
    op_src.BreakConnect();
  }

  if (status != SUCCESS) {
    REPORT_PREDEFINED_ERR_MSG("E11010", std::vector<const char *>({"opname", "optype"}),
                              std::vector<const char *>({node_proto->name().c_str(), op_type.c_str()}));
    GELOGE(status, "[Parse][Params] for op [%s] fail, optype [%s]", node_proto->name().c_str(), op_type.c_str());
    return status;
  }

  return SUCCESS;
}

Status OnnxModelParser::ParseAllNodeProto(ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
  for (int i = 0; i < onnx_graph.node_size(); i++) {
    ge::onnx::NodeProto *node_proto = onnx_graph.mutable_node(i);
    std::string node_name = node_proto->name();
    std::string ori_type = node_proto->op_type();
    GELOGI("Start parse node which name is %s, type is %s", node_name.c_str(), ori_type.c_str());

    std::string op_type;
    Status status = AdapterOpType(node_proto, ori_type, op_type);
    if (status != SUCCESS) {
      GELOGE(status, "[Adapt][OpType] Adapter op type for ori type %s failed.", ori_type.c_str());
      return status;
    }
    node_proto->set_op_type(ori_type);

    GELOGI("Trans original type:%s to op type:%s", ori_type.c_str(), op_type.c_str());

    ge::Operator op;
    status = TransNodeToOperator(node_proto, op, op_type);
    if (status != SUCCESS) {
      GELOGE(status, "[Trans][Node] Trans node to operator for %s:%s failed.", node_name.c_str(), op_type.c_str());
      REPORT_INNER_ERR_MSG("E19999", "Trans node to operator for %s:%s failed.", node_name.c_str(), op_type.c_str());
      return status;
    }

    // 7. op parser
    std::shared_ptr<ge::OpParserFactory> factory = ge::OpParserFactory::Instance(domi::ONNX);
    GE_CHECK_NOTNULL(factory);
    std::shared_ptr<ge::OpParser> op_parser = factory->CreateOpParser(op_type);
    GE_CHECK_NOTNULL(op_parser);
    status = ParseOpParam(node_proto, op, op_parser);
    if (status != SUCCESS) {
      GELOGE(status, "[Parse][Params] for %s:%s failed ret:%d.", node_name.c_str(), op_type.c_str(), status);
      return status;
    }

    GELOGI("After ParseParams, op[%s]: type[%s] have input size: %zu, output size: %zu",
           ParserUtils::GetOperatorName(op).c_str(), ParserUtils::GetOperatorType(op).c_str(), op.GetInputsSize(),
           op.GetOutputsSize());

    ge::graphStatus graph_status = graph.AddOp(op);
    if (graph_status != ge::GRAPH_SUCCESS) {
      GELOGE(FAILED, "[Add][Op] Add op:%s to graph failed.", ParserUtils::GetOperatorName(op).c_str());
      REPORT_INNER_ERR_MSG("E19999", "Add op:%s to graph failed.", ParserUtils::GetOperatorName(op).c_str());
      return FAILED;
    }
    name_operator_[ParserUtils::GetOperatorName(op)] = op;

    // 8. Construct input output relation of every node
    status = ConstructInputOutputContext(node_proto);
    if (status != SUCCESS) {
      REPORT_INNER_ERR_MSG("E19999", "ConstructInputOutputContext failed.");
      GELOGE(status, "[Construct][RelationMap] to input and output failed.");
      return status;
    }
  }
  GELOGI("Parse all node proto success.");
  return SUCCESS;
}

Status OnnxModelParser::GetGraphInputs(ge::onnx::GraphProto &onnx_graph, std::vector<ge::Operator> &input_ops) {
  if (input_node_names_.empty()) {
    // subgraph might not have input, we use constant nodes as the start nodes of the graph,
    for (int i = 0; i < onnx_graph.node_size(); i++) {
      ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
      if (node->op_type() == kOpTypeConstant) {
        input_node_names_.emplace_back(node->name());
      }
    }
  }
  for (auto in_name : input_node_names_) {
    std::map<std::string, ge::Operator>::const_iterator in_op = name_operator_.find(in_name);
    if (in_op == name_operator_.end()) {
      GELOGE(PARAM_INVALID, "[Get][Inputs] Model assigned input node name: %s cannot find in graph.", in_name.c_str());
      REPORT_INNER_ERR_MSG("E19999", "Model assigned input node name: %s cannot find in graph.", in_name.c_str());
      return PARAM_INVALID;
    }
    input_ops.emplace_back(in_op->second);
    GELOGI("Model assigned input node name: %s", ParserUtils::GetOperatorName(in_op->second).c_str());
  }
  return SUCCESS;
}

Status OnnxModelParser::AddNoInputNodesToGraph(ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
  auto compute_graph = ge::GraphUtilsEx::GetComputeGraph(graph);
  GE_CHECK_NOTNULL(compute_graph);
  for (int i = 0; i < onnx_graph.node_size(); i++) {
    const auto &node = onnx_graph.node(i);
    if (node.input_size() != 0) {
      continue;
    }
    if (compute_graph->FindNode(node.name()) != nullptr) {
      continue;
    }
    const auto iter = name_operator_.find(node.name());
    if (iter == name_operator_.end()) {
      continue;
    }
    (void)graph.AddNodeByOp(iter->second);
  }
  return SUCCESS;
}

Status OnnxModelParser::GetAllGraphNodes(ge::onnx::GraphProto &onnx_graph, std::vector<ge::Operator> &ops) const {
  for (int i = 0; i < onnx_graph.node_size(); i++) {
    ge::onnx::NodeProto *node = onnx_graph.mutable_node(i);
    const auto iter = name_operator_.find(node->name());
    GE_ASSERT_TRUE(iter != name_operator_.end(), "Cannot find node: %s in graph", node->name().c_str());
    ops.emplace_back(iter->second);
  }
  return SUCCESS;
}

Status OnnxModelParser::GetGraphOutputs(std::vector<std::pair<Operator, std::vector<size_t>>> &output_ops,
                                        ParserUtils::OutputMapping &out_tensor_to_nodes) {
  for (auto output_name : output_node_names_) {
    std::map<std::string, std::vector<std::pair<std::string, int>>>::const_iterator itr =
        outputs_map_.find(output_name);
    if (itr == outputs_map_.end()) {
      GELOGE(PARAM_INVALID, "[Get][Outputs] Cannot find output:%s in graph.", output_name.c_str());
      REPORT_INNER_ERR_MSG("E19999", "[Get][Outputs] Cannot find output:%s in graph.", output_name.c_str());
      return PARAM_INVALID;
    }

    std::vector<std::pair<std::string, int>> node_names_indexes = itr->second;
    for (const auto &node_name_index : node_names_indexes) {
      auto node_name = node_name_index.first;
      std::map<std::string, ge::Operator>::const_iterator out_op_itr = name_operator_.find(node_name);
      if (out_op_itr == name_operator_.end()) {
        GELOGE(PARAM_INVALID, "[Get][Operator] Cannot find operator: %s in graph.", node_name.c_str());
        REPORT_INNER_ERR_MSG("E19999", "Cannot find operator: %s in graph.", node_name.c_str());
        return PARAM_INVALID;
      }
      int index = node_name_index.second;
      output_ops.emplace_back(out_op_itr->second, vector<size_t>{static_cast<size_t>(index)});
      out_tensor_to_nodes[output_name] = std::make_pair(node_name, index);
      GELOGI("Out node index %d, node:%s", index, node_name.c_str());
    }
  }
  return SUCCESS;
}

Status OnnxModelParser::GetModelFromFile(const char *file, ge::onnx::ModelProto &onnx_model) const {
  GE_CHECK_NOTNULL(file);
  GELOGI("File path is %s.", file);

  // 1. Get graph from onnx model file.
  if (!ge::parser::ReadProtoFromBinaryFile(file, &onnx_model)) {
    REPORT_INNER_ERR_MSG("E19999", "Read onnx model file:%s failed.", file);
    GELOGE(PARAM_INVALID, "[Read][ModeFile] failed.");
    return FAILED;
  }

  if (SetExternalPath(file, onnx_model) != SUCCESS) {
    GELOGE(PARAM_INVALID, "[Set][ExternalPath] failed.");
    return PARAM_INVALID;
  }
  return SUCCESS;
}

Status OnnxModelParser::SetExternalPath(const char *file, ge::onnx::ModelProto &onnx_model) const {
  std::string real_path = ge::parser::RealPath(file);
  const size_t file_len = real_path.length();
  std::unique_ptr<char[]> tmp_file(new (std::nothrow) char[file_len + 1U]);
  GE_CHECK_NOTNULL(tmp_file);

  const auto ret = strncpy_s(tmp_file.get(), file_len + 1U, real_path.c_str(), file_len);
  if (ret != EN_OK) {
    REPORT_INNER_ERR_MSG("E19999", "strncpy_s failed, src=%s, dst=%p, src_len=%zu, dst_len=%zu, ret=%d.",
                         real_path.c_str(), static_cast<void *>(tmp_file.get()), file_len, file_len + 1U, ret);
    GELOGE(FAILED, "strncpy_s failed, src=%s, dst=%p, src_len=%zu, dst_len=%zu.", real_path.c_str(),
           static_cast<void *>(tmp_file.get()), file_len, file_len + 1U);
    return FAILED;
  }
  const char *const dir = mmDirName(tmp_file.get());
  GE_CHECK_NOTNULL(dir);

  const ge::onnx::GraphProto &onnx_graph = onnx_model.graph();
  for (int32_t i = 0; i < onnx_graph.initializer_size(); ++i) {
    const ge::onnx::TensorProto &initializer_tensor = onnx_graph.initializer(i);
    if (initializer_tensor.data_location() != ge::onnx::TensorProto_DataLocation_EXTERNAL) {
      continue;
    }
    for (int32_t j = 0; j < initializer_tensor.external_data_size(); ++j) {
      ge::onnx::StringStringEntryProto &string_proto =
          const_cast<ge::onnx::StringStringEntryProto &>(initializer_tensor.external_data(j));
      if (string_proto.key() != kLocation) {
        continue;
      }
      const std::string &file_name = string_proto.value();
      const std::string new_file = std::string(dir) + MMPA_PATH_SEPARATOR_STR + file_name;
      GELOGD("[%s] is external data. concat dir[%s] and file_name[%s], new_file[%s]", initializer_tensor.name().c_str(),
             dir, file_name.c_str(), new_file.c_str());
      string_proto.set_value(new_file);
    }
  }

  for (int32_t i = 0; i < onnx_graph.node_size(); ++i) {
    const ge::onnx::NodeProto &node_proto = onnx_graph.node(i);
    if (node_proto.op_type() != kOpTypeConstant) {
      continue;
    }
    for (int32_t j = 0; j < node_proto.attribute_size(); ++j) {
      const ge::onnx::AttributeProto &attribute_proto = node_proto.attribute(j);
      if (attribute_proto.name() != kAttrNameValue) {
        continue;
      }
      const ge::onnx::TensorProto &tensor_proto = attribute_proto.t();
      if (tensor_proto.data_location() != ge::onnx::TensorProto_DataLocation_EXTERNAL) {
        continue;
      }
      for (int32_t k = 0; k < tensor_proto.external_data_size(); ++k) {
        ge::onnx::StringStringEntryProto &string_proto =
            const_cast<ge::onnx::StringStringEntryProto &>(tensor_proto.external_data(k));
        if (string_proto.key() != kLocation) {
          continue;
        }
        const std::string &file_name = string_proto.value();
        const std::string new_file = std::string(dir) + MMPA_PATH_SEPARATOR_STR + file_name;
        GELOGD("[%s] is external data. concat dir[%s] and file_name[%s], new_file[%s]", node_proto.name().c_str(), dir,
               file_name.c_str(), new_file.c_str());
        string_proto.set_value(new_file);
      }
    }
  }
  return SUCCESS;
}

Status OnnxModelParser::GetModelFromMemory(const char *data, uint32_t size, ge::onnx::ModelProto &onnx_model) const {
  GE_CHECK_NOTNULL(data);

  // 1. Get graph from onnx model file.
  if (!ge::parser::ReadProtoFromArray(data, size, &onnx_model)) {
    REPORT_INNER_ERR_MSG("E19999", "Read onnx model from memory failed.");
    GELOGE(PARAM_INVALID, "[Read][OnnxModel] from memory failed.");
    return FAILED;
  }
  return SUCCESS;
}

void OnnxModelParser::ClearMembers() {
  name_operator_.clear();
  input_node_names_.clear();
  output_node_names_.clear();
  inputs_map_.clear();
  outputs_map_.clear();
}

Status OnnxModelParser::AdaptAndFindAllOnnxGraph(
    ge::onnx::GraphProto &root_onnx_graph, std::map<std::string, ge::onnx::GraphProto *> &name_to_onnx_graph) const {
  std::queue<ge::onnx::GraphProto *> onnx_graph_tasks;
  int index = 0;
  onnx_graph_tasks.push(&root_onnx_graph);

  while (!onnx_graph_tasks.empty()) {
    ge::onnx::GraphProto *onnx_graph = onnx_graph_tasks.front();
    onnx_graph_tasks.pop();
    std::string graph_name;
    for (const auto &graph_iter : name_to_onnx_graph) {
      if (graph_iter.second == onnx_graph) {
        graph_name = graph_iter.first;
        break;
      }
    }

    for (int i = 0; i < onnx_graph->node_size(); i++) {
      ge::onnx::NodeProto *node_proto = onnx_graph->mutable_node(i);
      if (node_proto->name().empty()) {
        std::string node_name = node_proto->op_type() + "_" + to_string(index++);
        node_proto->set_name(node_name);
      }
      GELOGD("adapt op name:%s, op type:%s", node_proto->name().c_str(), node_proto->op_type().c_str());

      SubgraphAdapterFactory *factory = SubgraphAdapterFactory::Instance();
      GE_CHECK_NOTNULL(factory);
      std::shared_ptr<SubgraphAdapter> subgraph_adapter = factory->CreateSubgraphAdapter(node_proto->op_type());
      if (subgraph_adapter == nullptr) {
        GELOGD("Do not need adapt subgraph, op type:%s", node_proto->op_type().c_str());
        continue;
      }
      std::vector<ge::onnx::GraphProto *> onnx_graphs;
      std::map<std::string, ge::onnx::GraphProto *> name_to_onnx_subgraph;
      if (subgraph_adapter->AdaptAndFindAllSubgraphs(node_proto, onnx_graphs, name_to_onnx_subgraph, graph_name) !=
          SUCCESS) {
        GELOGE(FAILED, "[Adapt][Subgraph] adapt subgraph of node:%s failed.", node_proto->name().c_str());
        REPORT_INNER_ERR_MSG("E19999", "adapt subgraph of node:%s failed.", node_proto->name().c_str());
        return FAILED;
      }

      for (const auto &sub_onnx_graph : onnx_graphs) {
        onnx_graph_tasks.push(sub_onnx_graph);
      }
      for (const auto &itr : name_to_onnx_subgraph) {
        name_to_onnx_graph.emplace(itr.first, itr.second);
      }
    }
  }
  return SUCCESS;
}

Status OnnxModelParser::ModelParseToGraph(const ge::onnx::ModelProto &onnx_model, ge::Graph &root_graph) {
  if (!onnx_model.has_graph()) {
    REPORT_PREDEFINED_ERR_MSG("E16004", std::vector<const char *>({}), std::vector<const char *>({}));
    GELOGE(PARAM_INVALID, "Onnx model do not has graph.");
    return FAILED;
  }
  std::map<std::string, ge::onnx::GraphProto *> name_to_onnx_graph;
  std::deque<ParseArg> tasks;
  ge::onnx::GraphProto root_onnx_graph = onnx_model.graph();

  auto ret = AdaptAndFindAllOnnxGraph(root_onnx_graph, name_to_onnx_graph);
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[AdaptAndFind][OnnxGraph]adapt and find all onnx graph failed, root graph:%s.",
           root_onnx_graph.name().c_str());
    return FAILED;
  }

  auto opset_import = onnx_model.opset_import();
  for (auto it : opset_import) {
    std::string domain = it.domain().empty() ? "ai.onnx" : it.domain();
    domain_verseion_[domain] = it.version();
    GELOGI("Domain:[%s], Version:[%ld].", domain.c_str(), it.version());
  }
  std::string root_graph_name =
      ParserUtils::GetGraphName(root_graph).empty() ? "default_graph" : ParserUtils::GetGraphName(root_graph);
  tasks.push_back({&root_onnx_graph, nullptr, root_graph_name, 0});

  while (!tasks.empty()) {
    ParseArg arg = tasks.front();
    tasks.pop_front();
    bool is_subgraph = (arg.parent_node != nullptr) ? true : false;

    if (arg.onnx_graph == nullptr) {
      std::map<std::string, ge::onnx::GraphProto *>::const_iterator itr = name_to_onnx_graph.find(arg.graph_name);
      if (itr == name_to_onnx_graph.end()) {
        GELOGI("Graph: %s is subgraph from plugin, no need parser", arg.graph_name.c_str());
        continue;
      }
      arg.onnx_graph = itr->second;
    }

    ge::onnx::GraphProto *onnx_graph = arg.onnx_graph;
    ge::Graph tmp_graph(arg.graph_name.c_str());
    ret = ModelParseToGraphImpl(is_subgraph, *onnx_graph, tmp_graph);
    if (ret != SUCCESS) {
      GELOGE(ret, "[Parse][Model] Model parse to graph failed, graph name:%s.", arg.graph_name.c_str());
      REPORT_INNER_ERR_MSG("E19999", "Model parse to graph failed, graph name:%s.", arg.graph_name.c_str());
      return ret;
    }
    // To get the result for root graph
    if (!is_subgraph) {
      root_graph = tmp_graph;
    }

    ge::ComputeGraphPtr cur_compute_graph = ge::GraphUtilsEx::GetComputeGraph(tmp_graph);
    if ((ge::GetParserContext().run_mode == ge::ONLY_PRE_CHECK) && (cur_compute_graph == nullptr)) {
      GELOGD("Only prechecker.");
      return SUCCESS;
    }
    GE_CHECK_NOTNULL(cur_compute_graph);

    ret = PostOpProcessForSubgraph(arg, cur_compute_graph);
    if (ret != SUCCESS) {
      GELOGE(ret, "[PostProcess][Subgraph]Post Op for subgraph:%s failed.", cur_compute_graph->GetName().c_str());
      REPORT_INNER_ERR_MSG("E19999", "Post Op for subgraph:%s failed.", cur_compute_graph->GetName().c_str());
      return ret;
    }

    ret = BuildLinkForChildAndParentGraph(cur_compute_graph, arg);
    if (ret != SUCCESS) {
      GELOGE(ret, "[BuildLink][Graph] Build link for child graph:%s and parent graph failed.",
             cur_compute_graph->GetName().c_str());
      REPORT_INNER_ERR_MSG("E19999", "Build link for child graph:%s and parent graph failed.",
                           cur_compute_graph->GetName().c_str());
      return ret;
    }

    ret = GenSubgraphParseTasks(cur_compute_graph, tasks);
    if (ret != SUCCESS) {
      GELOGE(ret, "[Generate][Task] Failed to gen tasks on graph %s for next iteration",
             cur_compute_graph->GetName().c_str());
      REPORT_INNER_ERR_MSG("E19999", "Failed to gen tasks on graph %s for next iteration",
                           cur_compute_graph->GetName().c_str());
      return ret;
    }
  }
  UpdateDataFormat(root_graph);
  return SUCCESS;
}

Status OnnxModelParser::ModelParseToGraphImpl(bool is_subgraph, ge::onnx::GraphProto &onnx_graph, ge::Graph &graph) {
  ClearMembers();
  GE_RETURN_WITH_LOG_IF_ERROR(ProtoTypePassManager::Instance().Run(&onnx_graph, domi::ONNX),
                              "Run ProtoType Pass Failed");
  // 1. Get all initializer.
  std::map<std::string, ge::onnx::TensorProto> initializer_name_tensor;
  for (int i = 0; i < onnx_graph.initializer_size(); i++) {
    ge::onnx::TensorProto initializer_tensor = onnx_graph.initializer(i);
    if (!initializer_tensor.name().empty()) {
      initializer_name_tensor[initializer_tensor.name()] = initializer_tensor;
      GELOGI("Initializer name:[%s].", initializer_tensor.name().c_str());
    }
  }

  // 2. Parse Input from graph.
  GELOGI("The size of initializer_name_tensor is %zu ", initializer_name_tensor.size());

  Status ret = ParseInput(initializer_name_tensor, is_subgraph, onnx_graph);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Parse][Input] for onnx failed.");
    return ret;
  }
  GELOGI("The size of initializer_name_tensor is %zu after ParseInput", initializer_name_tensor.size());

  // 3. Parse Constant(initializer) from graph.
  ret = ParseInitializer(onnx_graph, initializer_name_tensor);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Parse][Initializer] for onnx failed.");
    return ret;
  }

  // 4. Get all output name form origin graph
  ret = ParseOutput(onnx_graph);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Parse][Output] Parse output for onnx failed.");
    return ret;
  }

  // 5. Update node name for node do not has name, update const op type
  UpdateNodeNameAndOpType(onnx_graph);

  // 6 Precheck.
  ret = Prechecker(onnx_graph);
  bool is_precheck_failed = (ret != SUCCESS) || (ge::PreChecker::Instance().HasError());
  if (is_precheck_failed) {
    GELOGE(FAILED, "[Invoke][Prechecker] failed.");
    return FAILED;
  }

  if (ge::GetParserContext().run_mode == ge::ONLY_PRE_CHECK) {
    GELOGI("Only prechecker.");
    return SUCCESS;
  }

  // 7. Construct all operator and input output tensor relation.
  ret = ParseAllNodeProto(onnx_graph, graph);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Parse][AllNodeProto] failed.");
    return ret;
  }

  std::vector<AscendString> op_names;
  graph.GetAllOpName(op_names);
  GELOGI("After trans node to operator, graph has the size of operator is %zu.", op_names.size());

  // 8. Set all operator input.
  ret = SetOperatorInputs();
  if (ret != SUCCESS) {
    GELOGE(ret, "[Set][OperatorInputs] failed.");
    return ret;
  }

  // 9. Construct graph.
  std::vector<ge::Operator> input_ops;
  ret = GetGraphInputs(onnx_graph, input_ops);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Get][GraphInputs] failed.");
    return ret;
  }
  std::string topo_sorting_mode_str;
  ge::GetContext().GetOption(ge::OPTION_TOPOSORTING_MODE, topo_sorting_mode_str);
  const int32_t base = 10;
  auto topo_sorting_mode =
      topo_sorting_mode_str.empty()
          ? TopoSortingMode::kDFS
          : static_cast<TopoSortingMode>(std::strtol(topo_sorting_mode_str.c_str(), nullptr, base));
  if (topo_sorting_mode == TopoSortingMode::kStableRDFS) {
    std::vector<ge::Operator> ops;
    GE_ASSERT_SUCCESS(GetAllGraphNodes(onnx_graph, ops));
    GE_ASSERT_SUCCESS(GraphUtilsEx::CreateGraphFromOperatorWithStableTopo(graph, ops));
  } else {
    graph.SetInputs(input_ops);
    GE_ASSERT_SUCCESS(AddNoInputNodesToGraph(onnx_graph, graph));
  }

  // 10. Get output info and set outputs for subgraph
  std::vector<std::pair<Operator, std::vector<size_t>>> output_ops;
  ParserUtils::OutputMapping out_tensor_to_nodes;
  ret = GetGraphOutputs(output_ops, out_tensor_to_nodes);
  if (ret != SUCCESS) {
    GELOGE(ret, "[Get][Outputs] failed.");
    return ret;
  }
  // root graph needn't set outputs.
  if (is_subgraph) {
    graph.SetOutputs(output_ops);
  }

  // 11. Expand node to graph if need
  ParserUtils::OutputMapping final_output_nodes;
  GE_RETURN_IF_ERROR(ParserUtils::ExpandOneToManyGraph(graph, final_output_nodes));

  // 12. Set outputs info in ParserContext for root graph
  if (!is_subgraph) {
    ret = SetOutputsInfo(final_output_nodes, out_tensor_to_nodes);
    if (ret != SUCCESS) {
      GELOGE(ret, "[Set][OutputsInfo] Graph:%s.", ParserUtils::GetGraphName(graph).c_str());
      return ret;
    }
  }

  GELOGI("Onnx model parser success.");
  return SUCCESS;
}

Status OnnxModelParser::Parse(const char *file, ge::Graph &graph) {
  ge::onnx::ModelProto onnx_model;
  Status ret = GetModelFromFile(file, onnx_model);
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[Get][Model] From File:%s failed.", file);
    return FAILED;
  }
  ret = ModelParseToGraph(onnx_model, graph);
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[Parse][Model] To Graph failed.");
    return FAILED;
  }
  return SUCCESS;
}

Status OnnxModelParser::ParseFromMemory(const char *data, uint32_t size, ge::Graph &graph) {
  ge::onnx::ModelProto onnx_model;
  Status ret = GetModelFromMemory(data, size, onnx_model);
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[Get][Model] From Memory failed.");
    return FAILED;
  }
  ret = ModelParseToGraph(onnx_model, graph);
  if (ret != SUCCESS) {
    GELOGE(FAILED, "[Parse][Model] To Graph failed.");
    return FAILED;
  }
  return SUCCESS;
}

Status OnnxModelParser::ToJson(const char *model_file, const char *json_file) {
  if (model_file == nullptr) {
    REPORT_PREDEFINED_ERR_MSG("E13000", std::vector<const char *>({"path", "errmsg"}),
                              std::vector<const char *>({"", "param model file is nullptr"}));
    GELOGE(FAILED, "[Check][Param] Model file is nullptr.");
    return FAILED;
  }
  if (json_file == nullptr) {
    REPORT_PREDEFINED_ERR_MSG("E13000", std::vector<const char *>({"path", "errmsg"}),
                              std::vector<const char *>({"", "param json file is nullptr"}));
    GELOGE(FAILED, "[Check][Param]Json file is nullptr.");
    return FAILED;
  }

  ge::onnx::ModelProto onnx_model;
  GE_RETURN_WITH_LOG_IF_FALSE(ge::parser::ReadProtoFromBinaryFile(model_file, &onnx_model),
                              "[Invoke][ReadProtoFromBinaryFile] failed, file:%s.", model_file);
  ge::onnx::GraphProto graph_proto = onnx_model.graph();
  nlohmann::json j;
  ge::Pb2Json::Message2Json(graph_proto, std::set<std::string>(), j, true);
  return ge::parser::ModelSaver::SaveJsonToFile(json_file, j);
}

ge::DataType OnnxModelParser::ConvertToGeDataType(const uint32_t type) {
  return ge::OnnxUtil::ConvertOnnxDataType(type);
}

void OnnxModelParser::UpdateDataFormat(ge::Graph &graph) const {
  for (GNode &gn : graph.GetDirectNode()) {
    AscendString type;
    (void)gn.GetType(type);
    if (type != parser::DATA) {
      continue;
    }
    TensorDesc in_desc;
    gn.GetInputDesc(0, in_desc);
    ge::Format ge_format = TypeUtilsInner::DomiFormatToFormat(GetParserContext().format);
    in_desc.SetOriginFormat(ge_format);
    in_desc.SetFormat(ge_format);
    gn.UpdateInputDesc(0, in_desc);

    TensorDesc out_desc;
    gn.GetOutputDesc(0, out_desc);
    out_desc.SetOriginFormat(ge_format);
    out_desc.SetFormat(ge_format);
    gn.UpdateOutputDesc(0, out_desc);
  }
  GELOGD("Update data format success.");
  return;
}

Status OnnxModelParser::SetOutputsInfo(const ParserUtils::OutputMapping &final_output_nodes,
                                       const ParserUtils::OutputMapping &tensor_to_nodes) {
  // 记录一对多转换场景中原算子名称到子图实际输出名称的映射关系，传递给外部OMG流程用于更新输出算子相关信息（如datatype）
  auto &final_out_nodes_map = ge::GetParserContext().final_out_nodes_map;
  for (const auto &node_info : final_output_nodes) {
    (void)final_out_nodes_map.emplace(node_info.first, node_info.second);
  }

  auto &user_specified_nodes = ge::GetParserContext().user_out_nodes;
  if (!user_specified_nodes.empty()) {
    GELOGI("User specified the output nodes with node_name and index.");
    for (auto &output_node_info : user_specified_nodes) {
      ParserUtils::UpdateOutputNodeInfo(final_output_nodes, output_node_info);
    }
    return SUCCESS;
  }

  auto final_tensor_to_nodes = tensor_to_nodes;
  ParserUtils::UpdateOutputCtx(final_output_nodes, final_tensor_to_nodes);
  auto &user_specified_tensors = ge::GetParserContext().user_out_tensors;
  auto &output_tensor_names = ge::GetParserContext().out_tensor_names;
  output_tensor_names.clear();
  if (!user_specified_tensors.empty()) {
    for (auto &tensor_name : user_specified_tensors) {
      auto iter = final_tensor_to_nodes.find(tensor_name);
      if (iter != final_tensor_to_nodes.end()) {
        user_specified_nodes.emplace_back(iter->second);
        output_tensor_names.emplace_back(tensor_name);
        GELOGI("[UserSpecified]Add network output node[%s], index[%d], tensor name[%s].", iter->second.first.c_str(),
               iter->second.second, tensor_name.c_str());
      } else {
        REPORT_INNER_ERR_MSG("E19999", "User specified tensor[%s] is not output of graph.", tensor_name.c_str());
        GELOGE(FAILED, "[Set][OutputsInfo]User specified tensor[%s] is not output of graph.", tensor_name.c_str());
        return FAILED;
      }
    }
    return SUCCESS;
  }

  // for default output
  auto &default_out_nodes = ge::GetParserContext().default_out_nodes;
  for (auto &tensor_name : output_node_names_) {
    auto &output_node_info = final_tensor_to_nodes[tensor_name];
    default_out_nodes.emplace_back(output_node_info);
    output_tensor_names.emplace_back(tensor_name);
    GELOGI("[Default]Add network output node[%s], index[%d], tensor name[%s].", output_node_info.first.c_str(),
           output_node_info.second, tensor_name.c_str());
  }
  return SUCCESS;
}
}  // namespace ge

