39	Status OnnxFileConstantParser::ParseParams(const Message *op_src, ge::Operator &op_def) {
40	  GE_CHECK_NOTNULL(op_src);
41	  const ge::onnx::NodeProto *node = PtrToPtr<const Message, const ge::onnx::NodeProto>(op_src);
42	  GELOGD("Onnx op node name = %s, op type= %s, parse params", node->name().c_str(), node->op_type().c_str());
43	
44	  ge::onnx::TensorProto tensor_proto;
45	  if (GetTensorProto(*node, tensor_proto) != SUCCESS) {
46	    REPORT_INNER_ERR_MSG("E19999", "node[%s] get tensor failed", node->name().c_str());
47	    GELOGE(domi::PARAM_INVALID, "[Get][TensorProto] node[%s] get tensor failed", node->name().c_str());
48	    return FAILED;
49	  }
50	  if (ParseDataType(tensor_proto, op_def) != SUCCESS) {
51	    GELOGE(domi::PARAM_INVALID, "[Parse][Shape] node[%s] parse data type failed", node->name().c_str());
52	    return FAILED;
53	  }
54	  if (ParsePath(tensor_proto, op_def) != SUCCESS) {
55	    GELOGE(domi::PARAM_INVALID, "[Parse][Shape] node[%s] parse file path failed", node->name().c_str());
56	    return FAILED;
57	  }
58	  ParseShape(tensor_proto, op_def);
59	  return SUCCESS;
60	}
61	
62	Status OnnxFileConstantParser::GetTensorProto(const ge::onnx::NodeProto &node_proto,
63	                                              ge::onnx::TensorProto &tensor_proto) const {
64	  for (const auto &it : node_proto.attribute()) {
65	    if (it.name() != ge::kAttrNameValue) {
66	      continue;
67	    }
68	    tensor_proto = it.t();
69	    return SUCCESS;
70	  }
71	  REPORT_INNER_ERR_MSG("E19999", "node_proto[%s] get value failed", node_proto.name().c_str());
72	  GELOGE(ge::PARAM_INVALID, "[Get][TensorProto] node_proto[%s] get value failed", node_proto.name().c_str());
73	  return FAILED;
74	}
