76	void OnnxFileConstantParser::ParseShape(const ge::onnx::TensorProto &tensor_proto, ge::Operator &op_def) const {
77	  std::vector<int64_t> tmp_shape;
78	  for (int i = 0; i < tensor_proto.dims_size(); i++) {
79	    tmp_shape.push_back(tensor_proto.dims(i));
80	  }
81	  op_def.SetAttr(kAttrShape, tmp_shape);
82	}
