84	Status OnnxFileConstantParser::ParseDataType(const ge::onnx::TensorProto &tensor_proto, ge::Operator &op_def) const {
85	  int64_t data_type = tensor_proto.data_type();
86	  ge::DataType type = ge::OnnxUtil::ConvertOnnxDataType(data_type);
87	  if (type >= ge::DataType::DT_UNDEFINED) {
88	    REPORT_INNER_ERR_MSG("E19999", "tensor_proto data type %" PRId64 " is undefined.", data_type);
89	    GELOGE(domi::PARAM_INVALID, "[Check][Param] tensor_proto data type %" PRId64 " is undefined.", data_type);
