  std::map<std::string, CREATOR_FUN> *subgraph_adapter_creator_map = &subgraph_adapter_creator_map_;
  GELOGD("SubgraphAdapterFactory::RegisterCreator: op type:%s.", type.c_str());
  (*subgraph_adapter_creator_map)[type] = fun;
}
